	["a healing potion"] = "ein Heiltrank",
	["a hearthstone"] = "ein Ruhestein",
	["a light feather"] = "eine Leichte Feder",
	["a mage lets me fall so they won't fall to their death. What am I?"] = "ein Magier lässt mich fallen, damit er den Sturz übersteht. Was bin ich?",
