	["a soul shard"] = "ein Seelensplitter",
	["absently flips a coin across their knuckles."] = "lässt geistesabwesend eine Münze über die Fingerknöchel wandern.",
	["adjusts their jaw with a faint click."] = "rückt den Kiefer mit einem leisen Klicken zurecht.",
	["an ankh"] = "ein Ankh",
	["and I weep as I burn till there's nothing ahead. What am I?"] = "und ich weine im Brennen, bis nichts mehr bleibt, Tropf um Tropf. Was bin ich?",
	["and alchemists tremble to find me alone. What am I?"] = "und jeder Alchemist zittert, hält er mich in der Hand. Was bin ich?",
