	["answers: mount | mounts | horse | wolf | ram | raptor | kodo | mechanostrider | nightsaber | skeletal horse"] = { "reittier", "reittiere", "mount", "pferd", "wolf", "widder", "raptor", "kodo", "roboschreiter", "nachtsäbler", "skelettpferd" },
	["answers: murloc fin | murloc fins | fin | fins"] = { "murlocflosse", "murlocflossen", "flosse", "flossen" },
