	["arrows"] = "Pfeile",
	["beats down hard at the air with both hands, one after the other, quickly."] = "schlägt mit beiden Händen hart auf die Luft ein, eine nach der anderen, schnell.",
	["blinks slowly and looks down at their boots with a puzzled frown."] = "blinzelt langsam und schaut mit ratlosem Stirnrunzeln auf die Stiefel hinunter.",
	["blinks twice, slowly, at the fire."] = "blinzelt zweimal, langsam, ins Feuer.",
	["blows gently across an open palm."] = "bläst sanft über eine offene Handfläche.",
	["bows their head and moves their lips silently, slowly, as if learning the words."] = "senkt den Kopf und bewegt lautlos und langsam die Lippen, wie beim Auswendiglernen.",
	["bows their head and rocks slowly where they sit, matching the pace of something very old."] = "senkt den Kopf und wiegt sich langsam im Sitzen, im Takt von etwas sehr Altem.",
	["bows their head for a moment with their eyes shut tight, then opens one of them."] = "senkt einen Moment den Kopf, die Augen fest geschlossen, und öffnet dann eines davon.",
	["bows their head politely to the nearest log in the fire."] = "neigt höflich den Kopf vor dem nächstbesten Scheit im Feuer.",
	["bows their head toward the fire."] = "neigt den Kopf vor dem Feuer.",
	["bows their head with a small, rueful smile."] = "senkt den Kopf mit einem kleinen, reumütigen Lächeln.",
	["bows their head."] = "senkt den Kopf.",
	["bows three times, very small, from where they sit."] = "verbeugt sich dreimal im Sitzen, ganz klein.",
	["braces both hands against an invisible rail and looks sharply down."] = "stemmt beide Hände gegen ein unsichtbares Geländer und blickt jäh nach unten.",
	["braces their shoulder against something heavy and shoves, teeth bared."] = "stemmt die Schulter gegen etwas Schweres und schiebt mit gebleckten Zähnen.",
	["breaks an imaginary loaf in half and holds one piece out across the fire."] = "bricht einen unsichtbaren Laib in zwei Hälften und reicht ein Stück über das Feuer.",
	["breaks off a crumb and sets it carefully on one knee, without looking."] = "bricht einen Krümel ab und legt ihn, ohne hinzusehen, sorgfältig auf ein Knie.",
	["breaks off and turns one long ear toward the dark, utterly still."] = "bricht ab und dreht ein langes Ohr zur Dunkelheit, vollkommen reglos.",
	["breaks off and turns their head very slowly, as if someone had spoken just behind them."] = "bricht ab und dreht ganz langsam den Kopf, als käme von hinten eine Stimme.",
	["breathes in the drifting woodsmoke and closes their eyes."] = "atmet den ziehenden Holzrauch ein und schließt die Augen.",
	["breathes in the woodsmoke and, for a moment, seems to catch the smell of fresh bread instead."] = "atmet den Holzrauch ein und scheint für einen Moment stattdessen frisches Brot zu riechen.",
	["brings a fist up to their mouth, then lowers it again without a sound."] = "hebt die Faust vor den Mund und senkt sie lautlos wieder.",
	["brings their hands together once, very softly, then lets them part."] = "legt die Hände einmal ganz leise zusammen und lässt sie wieder auseinandergleiten.",
	["brushes one thumb in short, patient strokes across the palm of the other hand."] = "streicht mit einem Daumen in kurzen, geduldigen Strichen über die andere Handfläche.",
	["brushes the air in front of them with the side of one hand, slowly, like a broom."] = "fegt mit der Handkante langsam durch die Luft vor sich, wie mit einem Besen.",
	["brushes their own sleeve, then looks at their fingertips a moment too long."] = "streicht über den eigenen Ärmel und betrachtet dann einen Moment zu lange die Fingerspitzen.",
	["but after the hunt, I take something away. What am I?"] = "doch nach der Jagd nehm ich dem Wild sein Kleid. Was bin ich?",
	["but take one more hit, and I fall to the ground. What am I?"] = "doch trifft euch ein Schlag, bin ich's, der verschwindet. Was bin ich?",
	["chews slowly and deliberately, eyes fixed on the dark beyond the firelight."] = "kaut langsam und bedächtig, den Blick fest auf das Dunkel jenseits des Feuerscheins gerichtet.",
	["chuckles and pats their stomach."] = "lacht leise und klopft sich auf den Bauch.",
	["chuckles low in their throat."] = "lacht leise und tief in der Kehle.",
	["claps a hand to the top of their head, then slowly lowers it, finding nothing."] = "schlägt sich die Hand auf den Kopf und senkt sie langsam wieder, weil da nichts ist.",
	["clasps their hands around an imagined rod and draws their shoulders back."] = "legt die Hände um eine gedachte Angelrute und nimmt die Schultern zurück.",
	["clears their throat and waits for the circle to go quiet."] = "räuspert sich und wartet, bis die Runde still wird.",
	["clenches both fists tight, then throws them open."] = "ballt beide Fäuste fest und reißt sie dann auf.",
	["closes a fist around the washer, and the firelight goes out of it."] = "schließt die Faust um die Scheibe, und der Feuerschein darauf erlischt.",
	["closes both hands around an invisible rim and lowers their eyes."] = "legt beide Hände um einen unsichtbaren Rand und senkt den Blick.",
	["closes one hand slowly into a fist."] = "ballt langsam eine Hand zur Faust.",
	["closes the hand slowly and rests it on one knee."] = "schließt langsam die Hand und legt sie auf ein Knie.",
	["closes their eyes and nods slowly, keeping a beat that isn't there."] = "schließt die Augen und nickt langsam zu einem Takt, den es gar nicht gibt.",
	["closes their eyes and sits quietly, as if a great field lay all around them."] = "schließt die Augen und sitzt ganz still da, als läge ringsum ein weites Feld.",
	["closes their eyes for a moment."] = "schließt einen Moment lang die Augen.",
	["closes their hands, slowly, around nothing."] = "schließt die Hände langsam um nichts.",
	["cocks their head to one side and blinks, first one eye and then the other."] = "legt den Kopf schief und blinzelt, erst mit dem einen Auge, dann mit dem anderen.",
	["conjured water"] = "herbeigezaubertes Wasser",
	["conjures a loaf, knocks on it, and winces at the sound."] = "zaubert einen Laib Brot herbei, klopft darauf und zuckt bei dem Geräusch zusammen.",
	["copper ore"] = "Kupfererz",
	["coughs politely into one fist, then glances nervously behind them."] = "hüstelt höflich in die Faust und blickt sich dann nervös um.",
	["coughs, and becomes very interested in the fire."] = "hüstelt und interessiert sich plötzlich sehr für das Feuer.",
	["counts slowly on their fingers, and stops with one finger still raised."] = "zählt langsam an den Fingern ab und hält inne, einen Finger noch erhoben.",
	["counts the questions off on their fingers and runs out of fingers."] = "zählt die Fragen an den Fingern ab, und die Finger reichen nicht.",
	["counts the steps off on their fingers, then wrinkles their nose."] = "zählt die Schritte an den Fingern ab und rümpft dann die Nase.",
	["counts three points off on their fingers, then folds them away one by one."] = "zählt drei Punkte an den Fingern ab und klappt sie dann einen nach dem anderen wieder ein.",
	["cradles an invisible bowl in both hands, taking great care not to spill it."] = "hält eine unsichtbare Schale in beiden Händen und achtet sehr darauf, nichts zu verschütten.",
	["cradles something small in both hands and turns it over very carefully."] = "hält etwas Kleines in beiden Händen und dreht es ganz vorsichtig um.",
	["crumbles a heel of bread and lets it fall into the fire, one crumb at a time."] = "zerkrümelt einen Kanten Brot und lässt ihn ins Feuer rieseln, Krümel für Krümel.",
	["cups a hand as if holding something small and delicate."] = "wölbt eine Hand, als läge etwas Kleines, Zartes darin.",
	["cups a hand over one ear and turns their face from the fire."] = "legt eine hohle Hand über ein Ohr und wendet das Gesicht vom Feuer ab.",
	["cups a hand to one ear, as if listening to a far-off hum."] = "hält eine Hand hinters Ohr, wie um einem fernen Summen zu lauschen.",
	["cups a hand to their mouth and makes a sound like a dying goose."] = "legt die hohle Hand an den Mund und macht ein Geräusch wie eine sterbende Gans.",
	["cups an invisible flower in both hands, very carefully, as if it might fall apart."] = "hält eine unsichtbare Blume ganz behutsam in beiden Händen, als könnte sie zerfallen.",
	["cups an invisible lantern in both hands and mouths something at it, frowning."] = "hält mit beiden Händen eine unsichtbare Laterne und murmelt ihr stirnrunzelnd etwas zu.",
	["cups both hands together as if holding something small and damp."] = "legt beide Hände hohl zusammen, als hielten sie etwas Kleines, Feuchtes.",
	["cups both hands together, as if holding something very small."] = "legt beide Hände zu einer Schale zusammen, als läge etwas sehr Kleines darin.",
	["cups both hands together, then opens them slowly."] = "legt beide Hände hohl zusammen und öffnet sie dann langsam.",
	["cups one hand behind an ear, looks left, then looks right with growing disbelief."] = "legt eine Hand hinters Ohr, schaut nach links, dann mit wachsender Fassungslosigkeit nach rechts.",
	["cups one hand, as if holding something that might spill."] = "formt eine Hand zur Schale, wie um etwas zu halten, das überschwappen könnte.",
	["cups their hands around their mouth and hoots softly."] = "legt die Hände um den Mund und ruft leise: Huhuu.",
	["cups their hands gently, as though holding something small and warm."] = "formt sanft eine Schale mit den Händen, als hielten sie etwas Kleines, Warmes.",
	["curves one hand slowly through the air, as if guiding a growing branch."] = "führt eine Hand langsam im Bogen durch die Luft, wie um einen wachsenden Ast zu lenken.",
	["dabs their forehead and looks hopefully into an empty box."] = "tupft sich die Stirn und schaut hoffnungsvoll in eine leere Kiste.",
	["dangles a sock over the flames on a stick, feels it, and shakes their head."] = "hält eine Socke an einem Stock über die Flammen, befühlt sie und schüttelt den Kopf.",
	["dips their head to an invisible rock with exaggerated courtesy, then again with real courtesy."] = "neigt übertrieben höflich den Kopf vor einem unsichtbaren Stein, dann noch einmal, diesmal mit echter Höflichkeit.",
	["drags a heavy pack closer and gives it a thump."] = "zieht ein schweres Bündel heran und klopft einmal kräftig drauf.",
	["drags a stick slowly through the ashes, clearing a line, and says nothing yet."] = "zieht einen Stock langsam durch die Asche, bis eine Linie frei ist, und sagt noch nichts.",
	["draws a crooked line in the ashes with a stick, then tilts their head to read it upside down."] = "zieht mit einem Stock eine krumme Linie in die Asche und legt den Kopf schief, um sie verkehrt herum zu lesen.",
	["draws a faded blue ribbon from inside their sleeve and looks at it without speaking."] = "zieht ein verblichenes blaues Band aus dem Ärmel und betrachtet es schweigend.",
	["draws a long breath and squares their shoulders, as though walking into a wind."] = "holt tief Luft und strafft die Schultern, als ginge es gegen den Wind.",
	["draws a quick blade across the air and pulls one hand sharply free."] = "führt einen schnellen Schnitt durch die Luft und reißt eine Hand ruckartig frei.",
	["draws a single arrow from the quiver and turns it over in the firelight."] = "zieht einen einzelnen Pfeil aus dem Köcher und dreht ihn im Feuerschein.",
	["draws a slow circle in the air with one finger, and lets it fade."] = "zeichnet mit einem Finger langsam einen Kreis in die Luft und lässt ihn verblassen.",
	["draws a slow line through the air with one finger."] = "zieht mit einem Finger langsam eine Linie durch die Luft.",
	["draws a slow, grinning face in the air with one finger."] = "malt mit einem Finger langsam ein grinsendes Gesicht in die Luft.",
	["draws a straight line in the ashes with a stick, then slowly bends it into a curve."] = "zieht mit einem Stock eine gerade Linie in die Asche und biegt sie dann langsam zu einer Kurve.",
	["draws an imaginary arrow, then pauses to count the rest with one finger."] = "zieht einen unsichtbaren Pfeil und hält inne, um die übrigen mit einem Finger zu zählen.",
	["draws an imaginary purse from their coat and weighs it thoughtfully in one palm."] = "zieht einen unsichtbaren Beutel aus dem Mantel und wiegt ihn nachdenklich in einer Hand.",
	["draws back an invisible bowstring."] = "spannt eine unsichtbare Bogensehne.",
	["draws back, takes a deep breath, and flings both arms wide."] = "weicht zurück, holt tief Luft und reißt beide Arme weit auseinander.",
	["draws both hands in close, as if wrapping something tight around a pair of shoulders."] = "zieht beide Hände eng heran, wie um jemandem etwas fest um die Schultern zu legen.",
	["draws five small circles in the ashes with a stick, spacing them out."] = "malt mit einem Stock fünf kleine Kreise mit Abstand in die Asche.",
	["draws one hand back and forth in slow, patient strokes."] = "führt eine Hand in langsamen, geduldigen Strichen vor und zurück.",
	["draws one short line in the ashes with a stick and studies it."] = "zieht mit einem Stock einen kurzen Strich in die Asche und betrachtet ihn.",
	["draws the coals closer with a short stick and watches the smaller glow."] = "schiebt die Glut mit einem kurzen Stock zusammen und betrachtet das kleinere Glimmen.",
	["draws their shoulders inward and holds utterly still."] = "zieht die Schultern ein und verharrt völlig reglos.",
	["draws up their knees, lowers their head, and breathes out slowly."] = "zieht die Knie an, senkt den Kopf und atmet langsam aus.",
	["drops a splinter of wood into the coals and watches it go dark."] = "lässt einen Holzsplitter in die Glut fallen und sieht zu, wie er dunkel wird.",
	["ducks sharply forward, one arm flung out behind them."] = "duckt sich ruckartig nach vorn, einen Arm nach hinten weggeschleudert.",
	["ducks sharply, as though a stool just sailed over their head."] = "duckt sich blitzschnell, als wäre gerade ein Hocker über den Kopf gesegelt.",
	["dusts off their hands with great dignity."] = "klopft sich mit großer Würde die Hände ab.",
	["eases a fresh log onto the fire with great care, as one might tuck in something sleeping."] = "legt mit großer Sorgfalt ein frisches Scheit aufs Feuer, so wie man etwas Schlafendes zudeckt.",
	["edges a little closer to the flames and rubs both arms."] = "rückt ein Stück näher an die Flammen und reibt sich die Arme.",
	["edges back from the flames, tugs at their collar, and fans themselves furiously."] = "rückt vom Feuer ab, zerrt am Kragen und fächelt sich wie wild Luft zu.",
	["fans out an invisible hand of cards and counts them twice."] = "fächert ein unsichtbares Blatt Karten auf und zählt sie zweimal durch.",
	["fans out an invisible hand of cards and scowls at it."] = "fächert ein unsichtbares Blatt Karten auf und blickt finster drauf.",
	["fans their face with one hand."] = "fächelt sich mit einer Hand Luft zu.",
	["fans their open mouth with one hand, eyes watering."] = "fächelt sich mit einer Hand Luft in den offenen Mund, die Augen tränen.",
	["feeds a thin stick to the flames and watches it catch."] = "legt einen dünnen Zweig in die Flammen und sieht zu, wie er Feuer fängt.",
	["feeds one more stick to the flames, unhurried, so the fire stands a little taller against the dark."] = "legt ohne Eile noch einen Zweig in die Flammen, damit das Feuer ein wenig höher in die Dunkelheit ragt.",
	["feeds the fire a larger stick, glaring at a spot near their knee."] = "legt einen größeren Ast ins Feuer und funkelt eine Stelle neben dem Knie böse an.",
	["feeds the fire one more stick, though no one needs it, just in case."] = "legt noch einen Zweig nach, obwohl keiner ihn braucht. Nur für den Fall.",
	["feels forward with one hand, slowly, as though blind."] = "tastet sich langsam mit einer Hand vorwärts, wie blind.",
	["flexes one hand, as if still feeling the fight in it."] = "ballt eine Hand und öffnet sie wieder, als steckte der Kampf noch darin.",
	["flexes their off hand and looks at it as though it were an old friend."] = "bewegt die Finger der anderen Hand und betrachtet sie wie einen alten Freund.",
	["flicks an imaginary speck of ash from their sleeve."] = "schnippt ein unsichtbares Ascheflöckchen vom Ärmel.",
	["flinches and wipes the side of their face."] = "zuckt zusammen und wischt sich über die Wange.",
	["flinches as a log cracks and settles in the fire, then lays their hand back on their knee, one finger at a time."] = "zuckt zusammen, als ein Scheit im Feuer knackt und nachsackt, und legt die Hand dann wieder aufs Knie, Finger für Finger.",
	["flinches back, as if from a sudden burst of shadow."] = "zuckt zurück wie vor einem plötzlichen Schattenstoß.",
	["flinches from a popping spark and pats their singed eyebrows."] = "zuckt vor einem knisternden Funken zurück und betastet die angesengten Augenbrauen.",
	["flinches hard to one side, throwing an arm over their head."] = "zuckt heftig zur Seite und reißt einen Arm über den Kopf.",
	["flings a handful of dry grass on the fire and grins as it flares."] = "wirft eine Handvoll trockenes Gras ins Feuer und grinst, als es auflodert.",
	["flips a coin and catches it on the back of their hand."] = "wirft eine Münze hoch und fängt sie auf dem Handrücken.",
	["flips an invisible coin and catches it on the back of one hand."] = "wirft eine unsichtbare Münze hoch und fängt sie auf dem Handrücken.",
	["flutters their fingers downward like falling snow."] = "lässt die Finger herabflattern wie fallenden Schnee.",
	["folds an invisible scrap of paper small, then tucks it low with one finger."] = "faltet einen unsichtbaren Papierfetzen klein zusammen und schiebt ihn mit einem Finger tief unten drunter.",
	["folds an invisible sheet of paper in half, then in half again."] = "faltet ein unsichtbares Blatt Papier in der Mitte und dann noch einmal.",
	["folds one hand carefully over the other, as if tying the corners of a cloth."] = "legt behutsam eine Hand über die andere, wie um die Zipfel eines Tuchs zu verknoten.",
	["folds their arms and frowns down at an imaginary traveler."] = "verschränkt die Arme und blickt streng auf einen unsichtbaren Reisenden herab.",
	["folds their arms and stares into the fire with tremendous patience."] = "verschränkt die Arme und starrt mit gewaltiger Geduld ins Feuer.",
	["folds their hands and nods with immense, unhurried gravity."] = "faltet die Hände und nickt mit gewaltigem, gemächlichem Ernst.",
	["folds their hands and puts on a face of enormous patience."] = "faltet die Hände und setzt eine Miene von gewaltiger Geduld auf.",
	["folds their hands in their lap."] = "faltet die Hände im Schoß.",
	["follows one spark up until it goes out, and looks back down without a word."] = "folgt einem Funken nach oben, bis er erlischt, und blickt wortlos wieder nach unten.",
	["frames a small square in the air with their fingers, and peers through it."] = "formt mit den Fingern ein kleines Viereck in der Luft und späht hindurch.",
	["free for the thirsty who wander about. What am I?"] = "umsonst für die Durstigen, tagein und tagaus. Was bin ich?",
	["freezes mid-motion, eyes sliding toward the ground."] = "erstarrt mitten in der Bewegung, der Blick gleitet zu Boden.",
	["furrows their brow and thinks very slowly, tapping a finger on their chin."] = "runzelt die Stirn, tippt sich mit einem Finger ans Kinn und denkt sehr langsam nach.",
	["gathers a few twigs and lays them neatly at the edge of the fire."] = "sammelt ein paar Zweige und legt sie ordentlich an den Rand des Feuers.",
	["gathers the invisible cards together and holds them against their chest."] = "schiebt die unsichtbaren Karten zusammen und drückt sie an die Brust.",
	["gazes down at their open hands as if weighing something."] = "blickt auf die offenen Hände, wie um etwas abzuwägen.",
	["gazes into the flames, giving the question time to settle."] = "schaut in die Flammen und lässt die Frage erst einmal wirken.",
	["gazes off into the distance with great dignity."] = "blickt mit großer Würde in die Ferne.",
	["gazes solemnly into the distance, nodding, then looks down and sighs."] = "blickt feierlich nickend in die Ferne, senkt dann den Blick und seufzt.",
	["gazes through the heat shimmer above the fire, as though something blue might lie on the other side."] = "blickt durch das Flimmern über dem Feuer, als könnte auf der anderen Seite etwas Blaues liegen.",
	["gives a satisfied nod and brushes their palms together."] = "nickt zufrieden und klopft sich die Hände ab.",
	["gives a small, knowing smile."] = "lächelt leise und wissend.",
	["gives the burning log in the fire a long, respectful look."] = "wirft dem brennenden Scheit im Feuer einen langen, respektvollen Blick zu.",
	["gives the fire a small, apologetic nod, just in case."] = "nickt dem Feuer entschuldigend zu, nur für alle Fälle.",
	["gives {target} a good long look, then slides an invisible heel of bread across to them."] = "sieht {target} lange und gründlich an und schiebt dann einen unsichtbaren Brotkanten hinüber.",
	["glances at the empty space beside them, and shifts over a little."] = "schielt auf den leeren Platz neben sich und rückt ein Stückchen zur Seite.",
	["glances at the empty space beside them, then leans in a little closer to the fire."] = "blickt auf den leeren Platz neben sich und rückt dann ein wenig näher ans Feuer.",
	["glances at the flames, and for a moment does not seem certain what color they are."] = "schaut in die Flammen und scheint einen Moment lang nicht sicher, welche Farbe sie haben.",
	["glances at the sky, as if checking the hour."] = "blickt zum Himmel, wie um die Uhrzeit abzulesen.",
	["glances at their own shadow in the firelight, checking which way it falls."] = "wirft einen Blick auf den eigenen Schatten im Feuerschein und prüft, wohin er fällt.",
	["glances at {target}, then away, then back again."] = "schaut zu {target}, dann weg, dann wieder hin.",
	["glances back at their own shadow, stretched long behind them, and does not look for long."] = "wirft einen Blick zurück auf den eigenen, lang gestreckten Schatten und schaut nicht lange hin.",
	["glances down at about knee height and gives a long-suffering sigh."] = "blickt etwa auf Kniehöhe hinunter und seufzt lang und leidgeprüft.",
	["glances down at the campfire beside them and, very casually, shifts over a little."] = "wirft einen Blick auf das Lagerfeuer neben sich und rückt, ganz beiläufig, ein Stückchen weg.",
	["glances left, then right, then leans closer."] = "schaut nach links, dann nach rechts, und beugt sich näher heran.",
	["glances off toward the trees."] = "blickt hinüber zu den Bäumen.",
	["glances out at the dark beyond the firelight, then back at the circle."] = "späht hinaus ins Dunkel jenseits des Feuerscheins und dann zurück in die Runde.",
	["glances out past the firelight, as if checking something."] = "späht über den Feuerschein hinaus, wie um nach etwas zu sehen.",
	["glances out past the firelight, toward the dark between the trees."] = "blickt über den Feuerschein hinaus ins Dunkel zwischen den Bäumen.",
	["glances over at {target} and tips their head."] = "blickt zu {target} hinüber und neigt den Kopf.",
	["glances over one shoulder, then back again."] = "wirft einen Blick über die Schulter und dann wieder nach vorn.",
	["glances over one shoulder, then laughs a little too loudly."] = "wirft einen Blick über die Schulter und lacht dann eine Spur zu laut.",
	["glances over one shoulder, then mimes sliding something carefully back onto a high shelf."] = "schaut über die Schulter und schiebt dann etwas Unsichtbares vorsichtig zurück auf ein hohes Regal.",
	["glances over one shoulder, then pretends they didn't."] = "wirft einen Blick über die Schulter und tut dann so, als wäre nichts gewesen.",
	["glances over one shoulder, then turns back to the fire a little too quickly."] = "blickt über die Schulter und dreht sich dann ein wenig zu schnell wieder zum Feuer.",
	["glances past the firelight and counts something out there under their breath."] = "blickt über den Feuerschein hinaus und zählt dort draußen leise etwas ab.",
	["glances past {target} into the dark, and holds very still for a moment."] = "blickt an {target} vorbei in die Dunkelheit und hält einen Moment ganz still.",
	["glances sideways at the empty space next to them, as if keeping pace with it."] = "blickt zur Seite auf den leeren Platz neben sich, als hielte dort jemand Schritt.",
	["glances skyward out of habit."] = "wirft aus Gewohnheit einen Blick zum Himmel.",
	["glances up at the branches overhead, as though one of them might move."] = "blickt hinauf zu den Ästen, als könnte sich einer bewegen.",
	["glances up past the reach of the firelight, as if counting something overhead."] = "blickt hinauf, über den Feuerschein hinaus, wie um dort oben etwas zu zählen.",
	["glances up, as if at a high window, and flinches."] = "schaut hoch wie zu einem hohen Fenster und zuckt zusammen.",
	["goes completely still for a long moment, barely breathing."] = "wird für einen langen Moment völlig reglos und atmet kaum.",
	["goes completely still, one hand flat at their side, eyes fixed on nothing."] = "erstarrt völlig, eine Hand flach an der Seite, den Blick ins Leere gerichtet.",
	["goes quiet and lowers their eyes to the flames."] = "verstummt und senkt den Blick in die Flammen.",
	["goes quiet, letting the crackle of the fire fill the place where the answer would be."] = "verstummt und lässt das Knistern des Feuers die Stelle füllen, wo die Antwort hingehört.",
	["goes very still, and looks down at their empty hands."] = "wird ganz still und blickt auf die leeren Hände.",
	["grabs at something over their shoulder and leans back with all their weight."] = "greift nach etwas über der Schulter und stemmt sich mit dem ganzen Gewicht zurück.",
	["grabs at the air with both hands, then wrenches them sharply to one side."] = "greift mit beiden Händen in die Luft und reißt sie dann ruckartig zur Seite.",
	["grins across the fire."] = "grinst über das Feuer hinweg.",
	["grins and takes a long, satisfied drink."] = "grinst und nimmt einen langen, zufriedenen Schluck.",
	["grins wide, showing every tooth, and holds it a little too long."] = "grinst breit, zeigt jeden einzelnen Zahn und hält das Grinsen ein bisschen zu lange.",
	["grins, then hides the grin behind one hand."] = "grinst und versteckt das Grinsen dann hinter einer Hand.",
	["grips an imaginary set of levers and jerks them left and right."] = "packt ein paar unsichtbare Hebel und reißt sie nach links und rechts.",
	["grips an imagined club and gives one short, checked swing above their knee."] = "packt eine unsichtbare Keule und deutet einen kurzen, gebremsten Schlag über dem Knie an.",
	["grips an invisible rope in both fists, and leans back hard."] = "packt mit beiden Fäusten einen unsichtbaren Strick und stemmt sich kräftig nach hinten.",
	["grips an invisible sack by the neck and swings it round in a wide, low arc."] = "packt einen unsichtbaren Sack am Hals und schwingt ihn in einem weiten, flachen Bogen herum.",
	["grips an invisible staff that keeps trying to tilt to one side, and wrestles it upright."] = "packt einen unsichtbaren Stab, der dauernd zur Seite kippen will, und zwingt ihn wieder gerade.",
	["grips an invisible totem in both hands and drives it into the ground beside them."] = "packt mit beiden Händen ein unsichtbares Totem und rammt es neben sich in den Boden.",
	["grips reins and leans sharply to one side, cheeks puffed."] = "packt die Zügel und legt sich mit aufgeblasenen Backen scharf in die Kurve.",
	["grunts, a smile tugging at one tusk."] = "grunzt, ein Lächeln zupft an einem Hauer.",
	["gurgles deep in their throat, then wipes their chin with great dignity."] = "gurgelt tief in der Kehle und wischt sich dann mit großer Würde das Kinn ab.",
	["hauls hand over hand on an invisible rope, leaning back."] = "zieht Hand über Hand an einem unsichtbaren Seil und lehnt sich zurück.",
	["hefts an invisible, very heavy volume in both hands and squares up."] = "hebt mit beiden Händen einen unsichtbaren, sehr schweren Wälzer an und stellt sich breitbeinig hin.",
	["holds a flat hand low, then lets it slowly rise and sway."] = "hält eine flache Hand tief und lässt sie langsam steigen und schwanken.",
	["holds a hand out over the coals, palm down, and slowly draws it back."] = "hält eine Hand mit der Handfläche nach unten über die Glut und zieht sie langsam zurück.",
	["holds an invisible crate out at arm's length and leans their head away from it."] = "hält eine unsichtbare Kiste mit ausgestreckten Armen von sich und lehnt den Kopf davon weg.",
	["holds an invisible drawing out at arm's length and tilts their head at it."] = "hält eine unsichtbare Zeichnung auf Armlänge von sich und legt den Kopf schief.",
	["holds an invisible umbrella high overhead and squints up at it."] = "hält einen unsichtbaren Schirm hoch über den Kopf und blinzelt zu ihm hinauf.",
	["holds an invisible vial up to the light."] = "hält ein unsichtbares Fläschchen gegen das Licht.",
	["holds both arms out wide and lets them sink slowly, counting with small nods."] = "breitet beide Arme weit aus, lässt sie langsam sinken und zählt dabei mit leichtem Kopfnicken mit.",
	["holds both hands close together above the warmth."] = "hält beide Hände dicht beieinander über die Wärme.",
	["holds both hands out to the fire, as if they've gone cold."] = "hält beide Hände ans Feuer, als wären sie kalt geworden.",
	["holds both hands out toward the flames."] = "streckt beide Hände den Flammen entgegen.",
	["holds both palms out toward the fire, as if feeling warmth from something unseen."] = "hält beide Handflächen zum Feuer, als spürte die Haut die Wärme von etwas Unsichtbarem.",
	["holds both palms toward the fire for a long moment, as if checking that they still feel it."] = "hält beide Handflächen lange dem Feuer entgegen, wie um zu prüfen, ob sie es noch spüren.",
	["holds one boot out toward the flames and regards it with long-suffering sadness."] = "hält einen Stiefel zu den Flammen hin und betrachtet ihn mit leidgeprüfter Traurigkeit.",
	["holds one elbow up to the firelight and studies it for a long moment."] = "hält einen Ellbogen ins Feuerlicht und betrachtet ihn lange.",
	["holds one finger very still above an open palm, waiting."] = "hält einen Finger ganz still über einer offenen Handfläche und wartet.",
	["holds one forearm close against their chest, and reaches carefully up with the other."] = "drückt einen Unterarm eng an die Brust und greift vorsichtig mit dem anderen nach oben.",
	["holds one hand flat above their head and squints up from beneath it."] = "hält eine Hand flach über den Kopf und blinzelt darunter hervor nach oben.",
	["holds one hand halfway raised, eyes moving slowly left and right."] = "hält eine Hand halb erhoben, die Augen wandern langsam nach links und rechts.",
	["holds one hand out to the fire, the other still on the pouch, and seems unsure which is warmer."] = "hält eine Hand ans Feuer, die andere noch am Beutel, und scheint nicht sicher, was wärmer ist.",
	["holds one open palm out toward the fire, as if to have it read."] = "hält dem Feuer eine offene Handfläche hin, als solle es daraus lesen.",
	["holds out a cupped hand and drops invisible nails into it, one at a time."] = "hält eine hohle Hand hin und lässt unsichtbare Nägel hineinfallen, einen nach dem anderen.",
	["holds out a cupped hand, then slowly pushes it away."] = "hält eine hohle Hand hin und schiebt sie dann langsam weg.",
	["holds out a hand, as if feeling for a breeze."] = "streckt eine Hand aus, wie um einen Lufthauch zu erspüren.",
	["holds out an empty palm toward the fire, hopefully."] = "hält dem Feuer hoffnungsvoll eine leere Handfläche hin.",
	["holds out an invisible pen across the fire toward {target}."] = "hält {target} über das Feuer hinweg eine unsichtbare Feder hin.",
	["holds out an invisible spoon toward {target} with both hands, like a knight offering a sword."] = "hält {target} mit beiden Händen einen unsichtbaren Löffel hin, wie ein Ritter, der sein Schwert darbietet.",
	["holds out both hands and accepts something small, with visible surprise."] = "streckt beide Hände aus und nimmt sichtlich überrascht etwas Kleines entgegen.",
	["holds out both hands and regards them quietly."] = "streckt beide Hände aus und betrachtet sie still.",
	["holds out both hands as if warming a coat before a fire, turning it slowly."] = "hält beide Hände ans Feuer, wie um einen Mantel zu wärmen, und dreht ihn langsam.",
	["holds out cupped hands toward {target}, as if passing a bowl across the fire."] = "hält {target} die hohlen Hände hin, wie um eine Schüssel über das Feuer zu reichen.",
	["holds out cupped hands, very still."] = "hält ganz still die hohlen Hände hin.",
	["holds out one arm and scratches the air gently with the other hand."] = "streckt einen Arm aus und krault mit der anderen Hand sanft die Luft.",
	["holds out one arm, very still, and looks along it."] = "streckt einen Arm aus, ganz ruhig, und blickt daran entlang.",
	["holds out one hand as if guiding someone frail across a road."] = "streckt eine Hand aus, wie um jemand Gebrechlichen über die Straße zu führen.",
	["holds out one open palm and watches it closely."] = "hält eine offene Handfläche hin und beobachtet sie genau.",
	["holds still, then glances toward their own shadow and quickly back to the fire."] = "hält still, wirft dann einen Blick auf den eigenen Schatten und schaut schnell wieder ins Feuer.",
	["holds the back of one hand up to the firelight so an old scar shows, and looks at it for a while."] = "hält den Handrücken ins Feuerlicht, sodass eine alte Narbe sichtbar wird, und betrachtet sie eine Weile.",
	["holds the letter a moment too near the flames, then folds it carefully and tucks it away again."] = "hält den Brief einen Moment zu nah an die Flammen, faltet ihn dann sorgfältig und steckt ihn wieder weg.",
	["holds their hands apart as though measuring a very fine pair of boots."] = "hält die Hände auseinander, wie um ein Paar sehr feine Stiefel abzumessen.",
	["holds their hands close to the flames, turns them over, and regards them in silence."] = "hält die Hände nah an die Flammen, dreht sie um und betrachtet sie schweigend.",
	["holds their palms out to the flames and nods toward {target}'s side of the fire."] = "hält die Handflächen den Flammen entgegen und nickt zu der Seite des Feuers, an der {target} sitzt.",
	["holds two fingers very still, then twitches them a hair to one side, timing something."] = "hält zwei Finger ganz still und lässt sie dann um Haaresbreite zur Seite zucken, genau im richtigen Moment.",
	["holds two invisible halves apart and looks from one to the other."] = "hält zwei unsichtbare Hälften auseinander und blickt von der einen zur anderen.",
	["holds up a hand and counts along their fingers, then starts on the other hand."] = "hält eine Hand hoch und zählt an den Fingern ab, dann geht es an der anderen Hand weiter.",
	["holds up a hand with the thumb and finger a few inches apart, and smiles."] = "hält Daumen und Zeigefinger eine Handbreit auseinander und lächelt.",
	["holds up a small steel washer between finger and thumb."] = "hält eine kleine stählerne Unterlegscheibe zwischen Daumen und Zeigefinger hoch.",
	["holds up a thumb and finger, pinching something thin and small."] = "hält Daumen und Zeigefinger hoch, zwischen denen etwas Dünnes, Kleines steckt.",
	["holds up a thumb and forefinger, barely apart."] = "hält Daumen und Zeigefinger hoch, kaum einen Spalt auseinander.",
	["holds up a thumb and squints along it, measuring someone from a distance."] = "hält einen Daumen hoch und peilt daran entlang, wie um jemanden aus der Ferne zu vermessen.",
	["holds up a tiny invisible stone and squints at it."] = "hält einen winzigen unsichtbaren Stein hoch und kneift die Augen zusammen.",
	["holds up an imaginary blade, squints along it, and grimaces."] = "hält eine unsichtbare Klinge hoch, peilt daran entlang und verzieht das Gesicht.",
	["holds up an invisible carving and turns it around, frowning, trying another angle."] = "hält eine unsichtbare Schnitzerei hoch, dreht sie stirnrunzelnd hin und her und versucht es aus einem anderen Winkel.",
	["holds up an invisible scrap between two fingers."] = "hält einen unsichtbaren Fetzen zwischen zwei Fingern hoch.",
	["holds up an invisible vial and squints at it against the firelight."] = "hält ein unsichtbares Fläschchen gegen den Feuerschein und kneift prüfend ein Auge zu.",
	["holds up an invisible waterskin and shakes it, listening closely."] = "hält einen unsichtbaren Wasserschlauch hoch, schüttelt ihn und lauscht genau.",
	["holds up one finger and lets the question hang in the smoke."] = "hebt einen Finger und lässt die Frage im Rauch hängen.",
	["holds up one finger, as if the worst part is coming."] = "hebt einen Finger, als käme das Schlimmste erst noch.",
	["holds up one finger, thinks better of it, and opens both hands."] = "hebt einen Finger, überlegt es sich anders und öffnet beide Hände.",
	["holds up one hand and slowly closes it into a loose fist, not a tight one."] = "hebt eine Hand und schließt sie langsam zu einer lockeren Faust, nicht zu einer festen.",
	["holds up one hand as though steadying a lamp, and keeps it very still."] = "hält eine Hand wie mit einer Lampe in die Höhe und bewegt sie kein bisschen.",
	["holds up one hand with the fingers spread, studying it as though it belonged to someone else."] = "hält eine Hand mit gespreizten Fingern hoch und betrachtet sie, als gehöre sie jemand anderem.",
	["holds up something small between finger and thumb, turning it so the firelight slides along it."] = "hält etwas Kleines zwischen Daumen und Zeigefinger hoch und dreht es, sodass der Feuerschein darüber gleitet.",
	["holds up three fingers, then folds them down, one at a time."] = "hebt drei Finger und klappt sie dann einen nach dem anderen ein.",
	["holds up two empty fists and stares at them in remembered horror."] = "hält zwei leere Fäuste hoch und starrt sie an, das Entsetzen noch im Gesicht.",
	["holds up two fingers, side by side, and gazes at them fondly."] = "hält zwei Finger nebeneinander hoch und betrachtet sie liebevoll.",
	["holds up two fingers, then knocks them together."] = "hält zwei Finger hoch und stößt sie gegeneinander.",
	["holds up two fingers, then slowly lowers one of them."] = "hebt zwei Finger und senkt dann langsam einen davon.",
	["hums a few bars of an old marching song."] = "summt ein paar Takte eines alten Marschlieds.",
	["hums a few wandering notes that never quite settle into a song."] = "summt ein paar umherirrende Töne, die nie ganz zu einem Lied werden.",
	["hums the last notes again, more softly."] = "summt die letzten Töne noch einmal, leiser.",
	["hunches low and leans slowly forward, inch by inch."] = "duckt sich tief und schiebt sich langsam vor, Fingerbreit um Fingerbreit.",
	["hunches low and moves their hands slowly, as if sneaking."] = "duckt sich tief und bewegt die Hände langsam, wie beim Anschleichen.",
	["hunches low, gripping the air on either side and refusing to look down."] = "kauert sich tief, krallt sich links und rechts in die Luft und weigert sich, nach unten zu schauen.",
	["hunches low, grips an invisible rim, and leans hard into a turn."] = "duckt sich tief, packt einen unsichtbaren Rand und legt sich hart in eine Kurve.",
	["hunches low, one hand out for balance, and glances back with wide eyes."] = "duckt sich tief, eine Hand zum Gleichgewicht ausgestreckt, und blickt mit großen Augen zurück.",
	["hunches their shoulders and bares their teeth, growling softly."] = "zieht die Schultern hoch, bleckt die Zähne und knurrt leise.",
	["is quiet for a moment, then nods slowly."] = "schweigt einen Moment und nickt dann langsam.",
	["is quiet for a moment, watching the coals."] = "schweigt einen Moment und schaut in die Glut.",
	["is quiet for a moment."] = "schweigt einen Moment.",
	["jabs a thumb over one shoulder, toward some ridge in the dark."] = "deutet mit dem Daumen über die Schulter, zu irgendeinem Grat im Dunkeln.",
	["jerks forward suddenly, one arm wrenched out straight, teeth bared."] = "wird plötzlich nach vorn gerissen, einen Arm steif ausgestreckt, die Zähne gebleckt.",
	["jerks one fist forward, then draws back an imagined blade with the other hand."] = "stößt eine Faust nach vorn und zieht mit der anderen Hand eine unsichtbare Klinge zurück.",
	["keeps their eyes on the flames, as if still holding that light up for someone."] = "starrt in die Flammen, als gelte es noch immer, jemandem dieses Licht hochzuhalten.",
	["keeps their gaze fixed on the ground as they speak."] = "hält beim Sprechen den Blick fest auf den Boden gerichtet.",
	["knocks twice on the ground beside them."] = "klopft zweimal neben sich auf den Boden.",
	["laughs quietly into one hand."] = "lacht leise hinter vorgehaltener Hand.",
	["lays an invisible flower down beside them, very carefully."] = "legt ganz behutsam eine unsichtbare Blume neben sich.",
	["lays one hand flat on the ground, then the other beside it."] = "legt eine Hand flach auf den Boden und die andere daneben.",
	["lays one hand flat, then sets the other on top of it, very carefully."] = "legt eine Hand flach hin und setzt die andere sehr vorsichtig obendrauf.",
	["leans back and looks toward the water."] = "lehnt sich zurück und schaut zum Wasser hinüber.",
	["leans back and stretches both hands toward the warmth."] = "lehnt sich zurück und streckt beide Hände der Wärme entgegen.",
	["leans back with both hands behind their head."] = "lehnt sich zurück, beide Hände hinterm Kopf verschränkt.",
	["leans back, letting the firelight reach as far as it will."] = "lehnt sich zurück und lässt den Feuerschein so weit reichen, wie er will.",
	["leans back, still studying {target}, one eye narrowed."] = "lehnt sich zurück, mustert {target} weiter und kneift ein Auge zusammen.",
	["leans down and lays two fingers on the ground, then goes very still."] = "beugt sich hinunter, legt zwei Finger auf den Boden und erstarrt.",
	["leans down and presses one palm flat against the ground."] = "beugt sich hinunter und drückt eine Handfläche flach auf den Boden.",
	["leans down and studies the ground, then glances up, smirking."] = "beugt sich hinunter, studiert den Boden und blickt dann grinsend auf.",
	["leans forward and lowers their voice, one eye on the dark beyond the fire."] = "beugt sich vor und senkt die Stimme, ein Auge auf der Dunkelheit hinter dem Feuer.",
	["leans forward and pats their hands quickly against their knees, like feet on hard ground."] = "beugt sich vor und klopft mit den Händen schnell auf die Knie, wie Pfoten auf hartem Boden.",
	["leans forward and works at an imaginary keyhole, tongue between their teeth."] = "beugt sich vor und bearbeitet ein unsichtbares Schlüsselloch, die Zungenspitze zwischen den Zähnen.",
	["leans forward slightly, then back, then forward again, listening each time."] = "beugt sich leicht vor, dann zurück, dann wieder vor und lauscht jedes Mal.",
	["leans forward, pokes at something invisible with a stick, and sniffs thoughtfully."] = "beugt sich vor, stochert mit einem Stock in etwas Unsichtbarem und schnuppert nachdenklich.",
	["leans forward, raises one hand, and waits, watching the ground."] = "beugt sich vor, hebt eine Hand und wartet, den Blick auf den Boden gerichtet.",
	["leans hard to one side, arms braced, squinting into driving rain."] = "lehnt sich hart zur Seite, die Arme gestemmt, und blinzelt in peitschenden Regen.",
	["leans in and drops their voice, as if the captain might still overhear."] = "beugt sich vor und senkt die Stimme, als könnte die Kommandantin noch mithören.",
	["leans in close and drops their voice."] = "beugt sich vor und spricht ganz leise.",
	["leans in close to the fire and lowers their voice."] = "beugt sich nah ans Feuer und senkt die Stimme.",
	["leans in over the fire, so the light climbs their face, and lowers their voice."] = "beugt sich über das Feuer, sodass das Licht übers Gesicht hinaufkriecht, und senkt die Stimme.",
	["leans lightly on an invisible pole, barely pressing."] = "lehnt sich leicht auf eine unsichtbare Stange und drückt kaum.",
	["leans out with arms spread for balance, and glances down at a long drop."] = "lehnt sich mit ausgebreiteten Armen hinaus, um das Gleichgewicht zu halten, und blickt in eine lange Tiefe hinab.",
	["leans over and brushes something away with one hand, then looks closer."] = "beugt sich vor, wischt mit einer Hand etwas weg und schaut dann genauer hin.",
	["leans over and lifts a stone with great care."] = "beugt sich vor und hebt mit großer Sorgfalt einen Stein an.",
	["leans over and runs a hand across the grass, then wipes it on their coat."] = "beugt sich hinüber, streicht mit einer Hand übers Gras und wischt sie dann am Mantel ab.",
	["leans over to peer in the direction of {target}'s boots, then winces."] = "beugt sich vor, späht Richtung der Stiefel von {target} und verzieht dann das Gesicht.",
	["leans sideways with arms outspread, one hand clutching an imaginary wrench."] = "lehnt sich mit ausgebreiteten Armen zur Seite, in einer Hand einen unsichtbaren Schraubenschlüssel.",
	["leans to one side and peers around something tall, then winces."] = "beugt sich zur Seite, späht an etwas Hohem vorbei und verzieht das Gesicht.",
	["leans toward the fire, raises one finger, and tilts their head as though listening."] = "beugt sich zum Feuer, hebt einen Finger und legt lauschend den Kopf schief.",
	["leans toward the fire."] = "beugt sich zum Feuer vor.",
	["leans toward the firelight, as if about to share a secret."] = "beugt sich ins Licht des Feuers, als käme jetzt ein Geheimnis.",
	["leans toward {target} with great seriousness, hands folded."] = "beugt sich mit großem Ernst und gefalteten Händen zu {target} vor.",
	["leaves the second cup steaming at the edge of the stones."] = "lässt den zweiten Becher dampfend am Rand der Steine stehen.",
	["lets a long silence go by, watching the smoke above the flames."] = "lässt eine lange Stille verstreichen und schaut dem Rauch über den Flammen nach.",
	["lets go of the levers and raises both hands, grinning."] = "lässt die Hebel los und hebt grinsend beide Hände.",
	["lets go of their own sleeves and settles both hands in their lap."] = "lässt die eigenen Ärmel los und legt beide Hände in den Schoß.",
	["lets one hand hang low at their side, fingers moving as if scratching an ear."] = "lässt eine Hand tief an der Seite hängen, die Finger bewegen sich, als kraulten sie ein Ohr.",
	["lets one hand hang low, palm open, and leaves it there."] = "lässt eine Hand tief hängen, die Handfläche offen, und lässt sie dort.",
	["lets the fire tick and settle for a while before going on."] = "lässt das Feuer eine Weile knistern und zusammensinken, bevor es weitergeht.",
	["lets the silence sit a moment before saying anything else."] = "lässt die Stille einen Moment stehen, bevor noch ein Wort fällt.",
	["lets the silence sit so long that a log settling in the fire sounds loud."] = "lässt die Stille so lange stehen, dass ein Scheit, das im Feuer nachsackt, laut klingt.",
	["lets their eyes drift past the firelight into the dark, and keeps them there a little too long."] = "lässt den Blick über den Feuerschein hinaus ins Dunkel wandern und dort ein wenig zu lange verweilen.",
	["licks a fingertip, holds it up gravely, and nods as if it has told them something important."] = "leckt eine Fingerspitze ab, hält sie feierlich hoch und nickt, als hätte sie etwas Wichtiges verraten.",
	["lifts a cup carefully in both hands, then sniffs it."] = "hebt vorsichtig einen Becher mit beiden Händen an und schnuppert daran.",
	["lifts a hand in a small wave."] = "hebt eine Hand zu einem kleinen Winken.",
	["lifts a wet finger into the air, holds it there, and slowly lowers it."] = "hebt einen angefeuchteten Finger in die Luft, hält ihn dort und senkt ihn langsam wieder.",
	["lifts an invisible cup, blows across it, and sips with great care."] = "hebt eine unsichtbare Tasse, pustet darüber und nippt ganz vorsichtig.",
	["lifts an invisible heavy sack to shoulder height and holds it there, waiting."] = "stemmt einen unsichtbaren schweren Sack auf Schulterhöhe und hält ihn dort, abwartend.",
	["lifts an unseen plate and wipes it, very gently, with their sleeve."] = "hebt einen unsichtbaren Teller und wischt ihn ganz behutsam mit dem Ärmel ab.",
	["lifts one finger and gives a tiny invisible bell a single tap."] = "hebt einen Finger und tippt einmal an eine winzige unsichtbare Glocke.",
	["lifts one fist and brings it down sharply, as if striking with a hammer of light."] = "hebt eine Faust und lässt sie hart niedersausen, wie mit einem Hammer aus Licht.",
	["lifts one hand and studies the shadow it casts, turning it slowly."] = "hebt eine Hand, betrachtet den Schatten, den sie wirft, und dreht sie langsam.",
	["lifts one hand slowly, as if stepping over something, then lets it settle."] = "hebt langsam eine Hand, wie bei einem Schritt über etwas hinweg, und lässt sie dann sinken.",
	["lifts the lid of an invisible box, very slowly."] = "hebt ganz langsam den Deckel einer unsichtbaren Kiste.",
	["lifts the stone to their ear and goes quiet."] = "hält den Stein ans Ohr und wird ganz still.",
	["lifts their chin and answers softly to no one, \"Here.\""] = "hebt das Kinn und antwortet leise ins Leere: „Hier.“",
	["lifts their chin and looks down their nose, cold as a winter morning."] = "reckt das Kinn und schaut von oben herab, kalt wie ein Wintermorgen.",
	["lifts their chin and sniffs at the air, then wishes they hadn't."] = "hebt das Kinn, schnuppert in die Luft und bereut es sofort.",
	["lifts their hand off the ground beside the fire, slowly, and listens."] = "hebt die Hand neben dem Feuer langsam vom Boden und lauscht.",
	["linen cloth"] = "Leinenstoff",
	["links their fingers together, then pulls hard with both arms."] = "verschränkt die Finger ineinander und zieht dann mit beiden Armen kräftig.",
	["listens to the fire tick and pop, counting under their breath, then stops."] = "lauscht dem Knistern und Knacken des Feuers, zählt leise mit und hört dann auf.",
	["looks above the firelight for a long, quiet moment."] = "blickt lange und still über den Feuerschein hinaus.",
	["looks around at an unseen slope and gives a small, tired shrug."] = "blickt über einen unsichtbaren Hang und zuckt kurz und müde mit den Schultern.",
	["looks around the circle and lets the question hang, one eyebrow up."] = "blickt mit hochgezogener Augenbraue in die Runde und lässt die Frage in der Luft hängen.",
	["looks around the circle and nods once at each listener, as if daring one of them to ask."] = "blickt in die Runde und nickt jedem Zuhörer einmal herausfordernd zu.",
	["looks around the circle with raised eyebrows, waiting for someone to ask."] = "sieht mit hochgezogenen Augenbrauen in die Runde und wartet, dass jemand fragt.",
	["looks around the circle, daring someone to ask the obvious question."] = "blickt in die Runde und fordert jeden heraus, die naheliegende Frage zu stellen.",
	["looks at the ground near {target} and goes quiet."] = "blickt auf den Boden neben {target} und verstummt.",
	["looks at the log in their hand, and sets it down beside the fire instead of on it."] = "betrachtet das Scheit in der Hand und legt es neben das Feuer statt hinein.",
	["looks at their empty hands, then follows something slow along the ground with their eyes."] = "betrachtet die leeren Hände und folgt dann mit den Augen etwas Langsamem über den Boden.",
	["looks at their hands, then slowly folds them out of sight."] = "blickt auf die eigenen Hände und verbirgt sie dann langsam.",
	["looks at their open hand for a moment, then closes it gently."] = "betrachtet einen Moment die offene Hand und schließt sie dann sanft.",
	["looks at {target} across the flames for a little too long, then looks away."] = "sieht {target} über die Flammen hinweg einen Moment zu lange an und schaut dann weg.",
	["looks at {target}, then back into the fire."] = "sieht {target} an und dann wieder ins Feuer.",
	["looks away and runs a thumb slowly along the edge of their sleeve."] = "sieht weg und fährt mit dem Daumen langsam am Ärmelsaum entlang.",
	["looks down at the coals."] = "blickt hinab in die Glut.",
	["looks down at the fire, then at the ground beneath it, and nudges a stray coal back into the ring."] = "schaut ins Feuer, dann auf den Boden darunter, und schubst ein verirrtes Stück Glut zurück in den Kreis.",
	["looks down at their boots, not sure how to go on."] = "schaut hinunter auf die Stiefel und weiß nicht recht, wie es weitergehen soll.",
	["looks down at their hands and slowly opens them."] = "blickt auf die eigenen Hände und öffnet sie langsam.",
	["looks down at their hands, working at an invisible length of rope."] = "blickt auf die Hände hinab, die an einem unsichtbaren Stück Seil arbeiten.",
	["looks down at their own boot, and holds very still."] = "blickt auf den eigenen Stiefel hinab und hält ganz still.",
	["looks down at their own hands and turns them over slowly."] = "blickt auf die eigenen Hände und dreht sie langsam um.",
	["looks down at their wrist and gives it a small, testing shake."] = "blickt aufs Handgelenk hinab und schüttelt es prüfend ein wenig.",
	["looks down fondly at a spot near their feet."] = "blickt liebevoll auf eine Stelle neben den eigenen Füßen.",
	["looks down into their cup for a moment, smiling a little."] = "blickt eine Weile in den Becher und lächelt ein wenig.",
	["looks down, startled, and slowly lowers one raised arm."] = "blickt erschrocken an sich herab und senkt langsam einen erhobenen Arm.",
	["looks from one side to the other, slowly, and then back again."] = "blickt langsam von einer Seite zur anderen und wieder zurück.",
	["looks into the fire for a long moment, then nods once."] = "schaut lange ins Feuer und nickt dann einmal.",
	["looks into the fire."] = "schaut ins Feuer.",
	["looks off into the dark beyond the circle, jaw tight."] = "blickt mit zusammengebissenen Zähnen ins Dunkel jenseits des Kreises.",
	["looks off into the dark, as if counting distant campfires."] = "blickt hinaus ins Dunkel, wie beim Zählen ferner Lagerfeuer.",
	["looks off into the distance, as if over still water, and goes quiet for a moment."] = "blickt in die Ferne, wie über stilles Wasser, und wird für einen Moment still.",
	["looks out at some high, distant point and takes a slow breath."] = "blickt auf einen hohen, fernen Punkt und holt langsam Luft.",
	["looks out over the heads of the circle, as if at a far-off valley."] = "blickt über die Köpfe der Runde hinweg, wie hinab in ein fernes Tal.",
	["looks past the firelight at the black trees, and very carefully does not answer them."] = "blickt über den Feuerschein hinaus zu den schwarzen Bäumen und gibt ihnen ganz bewusst keine Antwort.",
	["looks skyward and slowly hunches their shoulders, as if something were circling."] = "blickt zum Himmel und zieht langsam die Schultern hoch, als kreiste dort etwas.",
	["looks slowly around the circle, at each face the firelight reaches, and then away."] = "blickt langsam in die Runde, in jedes Gesicht, das der Feuerschein erreicht, und wendet dann den Blick ab.",
	["looks slowly around the circle, lips moving as if counting."] = "blickt langsam in die Runde und bewegt dabei stumm die Lippen, wie beim Zählen.",
	["looks slowly down at their own hands, and draws them in close to the fire."] = "blickt langsam auf die eigenen Hände und zieht sie dicht ans Feuer.",
	["looks slowly to either side, searching, then lowers their gaze."] = "schaut langsam nach beiden Seiten, suchend, und senkt dann den Blick.",
	["looks slowly upward, then back down at the ground by their feet."] = "blickt langsam nach oben und dann wieder hinab auf den Boden vor den eigenen Füßen.",
	["looks up at the moon."] = "schaut hinauf zum Mond.",
	["looks up at the sky."] = "blickt hinauf zum Himmel.",
	["looks up slowly, then down at their own feet, frowning."] = "blickt langsam nach oben, dann stirnrunzelnd hinunter auf die eigenen Füße.",
	["looks up toward the mountains."] = "blickt hinauf zu den Bergen.",
	["looks {target} up and down, counting something on their fingers."] = "mustert {target} von oben bis unten und zählt dabei etwas an den Fingern ab.",
	["lowers a bow and breathes out slowly."] = "senkt einen Bogen und atmet langsam aus.",
	["lowers an invisible lantern slowly, then stops short and pulls it back."] = "senkt langsam eine unsichtbare Laterne, hält dann jäh inne und zieht sie zurück.",
	["lowers the invisible spoon and shakes their head slowly."] = "senkt den unsichtbaren Löffel und schüttelt langsam den Kopf.",
	["lowers their gaze and walks two fingers slowly along one knee, as if following something along the ground."] = "senkt den Blick und lässt zwei Finger langsam über ein Knie wandern, als folgten sie einer Spur am Boden.",
	["lowers their head and rests both hands on their weapon."] = "senkt den Kopf und stützt beide Hände auf die Waffe.",
	["lowers their head and sinks their shoulders slowly, like something going under."] = "senkt den Kopf und lässt langsam die Schultern sinken, wie etwas, das untergeht.",
	["lowers their voice and glances over one shoulder at nobody."] = "senkt die Stimme und blickt über die Schulter, wo niemand ist.",
	["lowers their voice and glances toward the dark past the fire."] = "senkt die Stimme und blickt hinaus ins Dunkel hinter dem Feuer.",
	["lowers their voice."] = "senkt die Stimme.",
	["lunges forward and snaps one hand shut, then hauls it back."] = "stürzt nach vorn, schnappt mit einer Hand zu und reißt sie zurück.",
	["makes a small gurgling noise, then looks embarrassed."] = "gibt ein leises Gurgeln von sich und schaut dann verlegen drein.",
	["makes a small, courteous bow, then another, then catches themselves halfway through a third."] = "macht eine kleine, höfliche Verbeugung, dann noch eine, und bricht mitten in der dritten ab.",
	["mimes a short, patient tap against the ground, over and over."] = "deutet ein kurzes, geduldiges Klopfen auf den Boden an, immer und immer wieder.",
	["mimes lifting the lid of a heavy chest, then lets their shoulders drop."] = "hebt pantomimisch den Deckel einer schweren Truhe und lässt dann die Schultern sinken.",
	["mimes peeling something wet from their sleeve, with growing disgust."] = "zieht pantomimisch etwas Nasses vom Ärmel, mit wachsendem Ekel.",
	["mimes reaching down, lifting, and setting something gently on the ground."] = "bückt sich pantomimisch, hebt etwas auf und stellt es behutsam auf den Boden.",
	["mimes shaping a snowball between their palms and gives one short, hopeless throw."] = "formt pantomimisch einen Schneeball zwischen den Handflächen und macht einen kurzen, hoffnungslosen Wurf.",
	["mouths a word carefully and silently, as if practicing it."] = "formt lautlos und sorgfältig ein Wort mit den Lippen, wie zur Übung.",
	["moves one hand as if brushing through hanging leaves."] = "bewegt eine Hand wie durch herabhängendes Laub.",
	["moves one hand forward, stops it suddenly, and waits with their head on one side."] = "bewegt eine Hand nach vorn, hält sie plötzlich an und wartet mit schief gelegtem Kopf.",
	["moves their lips silently for a moment, eyes closed."] = "bewegt einen Moment lang stumm die Lippen, die Augen geschlossen.",
	["narrows their eyes and leans closer to something invisible, then draws back sharply."] = "kneift die Augen zusammen, beugt sich zu etwas Unsichtbarem vor und zuckt dann jäh zurück.",
	["narrows their eyes and shifts their weight, as if sizing someone up."] = "kneift die Augen zusammen und verlagert das Gewicht, wie um einen Gegner einzuschätzen.",
	["narrows their eyes at {target}, then slowly grins."] = "mustert {target} mit schmalen Augen und fängt dann langsam an zu grinsen.",
	["narrows their eyes, as though at some small and hated foe."] = "kneift die Augen zusammen, wie vor einem kleinen, verhassten Feind.",
	["nods at the fire and shows their tusks in a wide, lazy grin."] = "nickt zum Feuer hin und zeigt die Hauer in einem breiten, trägen Grinsen.",
	["nods once, as if that's the end of the matter."] = "nickt einmal, als wäre damit alles gesagt.",
	["nods slowly and approvingly, as if at a fine piece of work."] = "nickt langsam und anerkennend, wie bei einem gelungenen Stück Arbeit.",
	["nods solemnly at {target}."] = "nickt {target} feierlich zu.",
	["nods to {target} and settles back."] = "nickt {target} zu und lehnt sich zurück.",
	["nudges a log deeper into the coals."] = "schiebt ein Scheit tiefer in die Glut.",
	["nudges a log deeper into the fire and watches the sparks climb."] = "schiebt ein Holzscheit tiefer ins Feuer und sieht den Funken nach.",
	["opens a pack, reaches in, and pulls their hand back quickly."] = "öffnet einen Rucksack, greift hinein und zieht die Hand schnell wieder zurück.",
	["opens one hand and studies the middle of the palm in the firelight."] = "öffnet eine Hand und betrachtet im Feuerschein die Mitte der Handfläche.",
	["opens one hand slowly and looks at what would be lying in it."] = "öffnet langsam eine Hand und betrachtet, was darin liegen würde.",
	["opens one hand to reveal a small, dark seed, worn smooth with handling."] = "öffnet eine Hand und zeigt einen kleinen, dunklen Samen, ganz glatt vom vielen Anfassen.",
	["opens their mouth to answer, then thoughtfully closes it."] = "öffnet den Mund zu einer Antwort und schließt ihn dann nachdenklich wieder.",
	["opens their mouth to speak, then closes it and looks down at their hands."] = "öffnet den Mund, um etwas zu sagen, schließt ihn wieder und blickt auf die eigenen Hände.",
	["passes something heavy from one hand to the other, again and again, quickly."] = "reicht etwas Schweres von einer Hand in die andere, immer wieder, schnell.",
	["pats a small pouch at their belt, and lets their hand stay there."] = "klopft auf einen kleinen Beutel am Gürtel und lässt die Hand dort liegen.",
	["pats an invisible pack at their side."] = "klopft auf einen unsichtbaren Beutel an der Seite.",
	["pats the air at shoulder height, as if feeling for something worn."] = "tastet in Schulterhöhe durch die Luft, als suchte die Hand nach etwas Abgenutztem.",
	["pats the empty ground beside them."] = "klopft neben sich auf den leeren Boden.",
	["pats the ground beside them as if greeting an old friend, nodding slowly."] = "tätschelt den Boden neben sich, wie zur Begrüßung eines alten Freundes, und nickt langsam.",
	["pats their own face and arms, as if checking they're all still there."] = "tastet Gesicht und Arme ab, wie um zu prüfen, ob noch alles da ist.",
	["pats their pack gently."] = "klopft sanft auf den Rucksack.",
	["pats their pockets, then turns one inside out."] = "klopft die Taschen ab und stülpt dann eine nach außen.",
	["pats their stomach slowly with one hand, looking wounded."] = "tätschelt langsam mit einer Hand den Bauch und schaut gekränkt.",
	["pats their stomach, then holds up one finger as though something has just occurred to them."] = "klopft sich auf den Bauch und hebt dann einen Finger, als wäre da gerade ein Gedanke gekommen.",
	["pats their thigh twice, softly, and looks down."] = "klopft sich zweimal sanft auf den Oberschenkel und blickt nach unten.",
	["pauses with an imaginary spoon halfway to their mouth."] = "hält inne, einen unsichtbaren Löffel auf halbem Weg zum Mund.",
	["pauses with an invisible spoon halfway to their mouth, then slowly lowers it."] = "hält inne, einen unsichtbaren Löffel auf halbem Weg zum Mund, und senkt ihn dann langsam.",
	["pauses, and raises a hand as if holding up a lantern."] = "hält inne und hebt eine Hand, wie um eine Laterne hochzuhalten.",
	["peacebloom"] = "Friedensblume",
	["peels back a blanket and peers in, without any sudden movements."] = "schlägt eine Decke zurück und späht hinein, ohne jede hastige Bewegung.",
	["peels something sticky off their sleeve, and then has trouble getting it off their fingers."] = "zupft etwas Klebriges vom Ärmel und kriegt es dann nicht mehr von den Fingern.",
	["peers at the ground near {target}, watching how the firelight falls."] = "späht auf den Boden neben {target} und beobachtet, wie der Feuerschein fällt.",
	["peers between their fingers, as if through leaves, at something far off."] = "späht zwischen den Fingern hindurch wie durch Laub, auf etwas in weiter Ferne.",
	["peers down into cupped hands, searching for something small."] = "späht in die hohlen Hände hinab, auf der Suche nach etwas Kleinem.",
	["peers into a bowl, then gives it a polite nod."] = "späht in eine Schüssel und nickt ihr dann höflich zu.",
	["peers off toward the hills, chewing slowly."] = "späht zu den Hügeln hinüber und kaut langsam.",
	["peers over an imaginary edge and slowly draws back, swallowing."] = "späht über eine unsichtbare Kante, schluckt und weicht langsam zurück.",
	["peers suspiciously into an imaginary bowl and stirs it with one finger."] = "späht misstrauisch in eine unsichtbare Schüssel und rührt mit einem Finger darin.",
	["picks a twig from the kindling, considers how long it took to grow, and feeds it to the fire anyway."] = "zieht einen Zweig aus dem Anmachholz, bedenkt, wie lange er zum Wachsen gebraucht hat, und füttert das Feuer trotzdem damit.",
	["picks an invisible crumb from their own chin, and studies it."] = "pickt einen unsichtbaren Krümel vom eigenen Kinn und betrachtet ihn genau.",
	["picks an invisible lock with two fingers, then freezes with their head cocked."] = "knackt mit zwei Fingern ein unsichtbares Schloss und erstarrt dann mit schief gelegtem Kopf.",
	["picks at an invisible knot with blunt, patient fingers."] = "nestelt mit stumpfen, geduldigen Fingern an einem unsichtbaren Knoten.",
	["picks at an invisible knot with their fingertips, frowning."] = "zupft mit den Fingerspitzen an einem unsichtbaren Knoten und runzelt die Stirn.",
	["pinches an invisible line between two fingers and lets it droop slowly."] = "nimmt eine unsichtbare Leine zwischen zwei Finger und lässt sie langsam durchhängen.",
	["pinches an invisible needle and draws a slow thread through the air."] = "hält eine unsichtbare Nadel zwischen den Fingern und zieht langsam einen Faden durch die Luft.",
	["pinches an invisible thread and lifts it carefully clear of something below."] = "fasst einen unsichtbaren Faden und hebt ihn vorsichtig über etwas hinweg.",
	["pitches forward with arms spread wide, then jerks upward as if yanked by the collar."] = "kippt mit ausgebreiteten Armen nach vorn und ruckt dann nach oben, wie am Kragen zurückgerissen.",
	["plants both hands flat on their knees and sets their shoulders, immovable."] = "legt beide Hände flach auf die Knie und strafft die Schultern, unverrückbar.",
	["plants their fists on their hips and glares at the ground, jaw thrust forward."] = "stemmt die Fäuste in die Hüften und starrt finster auf den Boden, das Kinn vorgeschoben.",
	["plants their hands on their hips and looks up, like someone addressing a stubborn child."] = "stemmt die Hände in die Hüften und blickt nach oben, wie jemand, der ein bockiges Kind zurechtweist.",
	["plants their hands on their hips and surveys a vast and empty view."] = "stemmt die Hände in die Hüften und überblickt eine weite, leere Landschaft.",
	["points around in a slow circle, lips moving silently."] = "zeigt langsam im Kreis herum, die Lippen bewegen sich lautlos.",
	["points at two spots on their open palm, one and then the other."] = "zeigt auf zwei Stellen der offenen Handfläche, erst auf die eine, dann auf die andere.",
	["points left with one hand, right with the other, and then tries to point up with an elbow."] = "zeigt mit der einen Hand nach links, mit der anderen nach rechts und versucht dann, mit dem Ellbogen nach oben zu zeigen.",
	["points left, then right, then gives their own hand a puzzled look."] = "zeigt nach links, dann nach rechts und betrachtet dann ratlos die eigene Hand.",
	["points north with a stick from the fire."] = "zeigt mit einem Stock aus dem Feuer nach Norden.",
	["points once toward the fire ring, pauses, and lowers their hand without finishing the count."] = "zeigt einmal auf den Steinring ums Feuer, stockt und lässt die Hand sinken, ohne zu Ende zu zählen.",
	["points slowly around the circle where they sit, at nothing in particular."] = "zeigt langsam im Kreis herum, auf nichts Bestimmtes.",
	["pokes a stick into the coals and considers it gravely."] = "stößt einen Stock in die Glut und betrachtet ihn ernst.",
	["pokes at the fire and watches the sparks climb."] = "stochert in der Glut und sieht den Funken nach, die in den Himmel steigen.",
	["pokes the fire and watches the sparks climb."] = "stochert im Feuer und sieht den Funken nach, die aufsteigen.",
	["pokes the fire twice and clears their throat, a little too loudly."] = "stochert zweimal im Feuer und räuspert sich, ein bisschen zu laut.",
	["pokes the fire until it crackles, then looks around the circle."] = "stochert im Feuer, bis es knistert, und blickt dann in die Runde.",
	["pokes their tongue into their cheek and winces."] = "drückt die Zunge gegen die Wange und zuckt zusammen.",
	["pops something imaginary into their mouth and chews happily."] = "steckt sich etwas Unsichtbares in den Mund und kaut zufrieden.",
	["pounds out a rhythm on their thigh that falls apart almost at once."] = "trommelt einen Rhythmus auf den Oberschenkel, der fast sofort auseinanderfällt.",
	["presses a hand flat over their heart and lets out a long breath."] = "legt eine Hand flach aufs Herz und atmet lange aus.",
	["presses a palm flat against their chest, then lets it fall."] = "drückt eine Handfläche flach auf die Brust und lässt sie dann sinken.",
	["presses an ear to an unseen pipe and holds their breath."] = "presst ein Ohr an ein unsichtbares Rohr und hält den Atem an.",
	["presses one finger to their lips and looks up, not moving at all."] = "legt einen Finger an die Lippen und schaut nach oben, völlig reglos.",
	["presses one palm against the empty air and slowly draws it back."] = "drückt eine Handfläche gegen die leere Luft und zieht sie langsam zurück.",
	["presses one thumb gently into the center of their other palm."] = "drückt einen Daumen sanft in die Mitte der anderen Handfläche.",
	["presses their lips together and gives a small, stiff nod."] = "presst die Lippen zusammen und nickt knapp und steif.",
	["presses their thumb into the palm of their other hand and holds it there."] = "drückt einen Daumen in die Handfläche der anderen Hand und hält ihn dort fest.",
	["pretends to gallop with both hands."] = "mimt mit beiden Händen einen Galopp.",
	["pretends to pour something from nothing."] = "schenkt scheinbar etwas aus dem Nichts ein.",
	["prods a charred log with a stick, twice, just to be sure."] = "stupst zweimal mit einem Stock an ein verkohltes Scheit, nur um sicherzugehen.",
	["puckers their mouth and swallows hard at the memory."] = "verzieht den Mund und schluckt bei der Erinnerung schwer.",
	["puffs out their cheeks and frowns up at the sky."] = "bläst die Backen auf und blickt finster zum Himmel.",
	["puffs out their chest proudly, then lets it sag."] = "wirft stolz die Brust raus und lässt sie dann wieder sinken.",
	["puffs up their chest."] = "wirft sich in die Brust.",
	["pulls a knot tight in an invisible rope, and keeps both hands on it."] = "zieht einen Knoten in einem unsichtbaren Seil fest und lässt beide Hände darauf liegen.",
	["pulls a loose thread from their sleeve and drops it in the flames without a word."] = "zupft einen losen Faden aus dem Ärmel und lässt ihn wortlos in die Flammen fallen.",
	["pulls a loose thread from their sleeve and lets the updraft off the fire carry it away."] = "zupft einen losen Faden aus dem Ärmel und lässt ihn vom Aufwind des Feuers davontragen.",
	["pulls a small feather from nowhere and smooths it between their fingers."] = "zieht eine kleine Feder aus dem Nichts und streicht sie zwischen den Fingern glatt.",
	["pulls a worn spoon from their belt and gives it a little flourish."] = "zieht einen abgewetzten Löffel aus dem Gürtel und schwenkt ihn mit einer kleinen Verbeugung.",
	["pulls an invisible folded letter from a pocket and frowns at it, then at {target}."] = "zieht einen unsichtbaren gefalteten Brief aus der Tasche und runzelt die Stirn, erst über den Brief, dann über {target}.",
	["pulls at something around their neck, and holds the end up to look at it."] = "zupft an etwas, das um den Hals hängt, und hebt das Ende hoch, um es anzusehen.",
	["pulls off an invisible coat, throws it over something, then tugs gently on a lead."] = "zieht einen unsichtbaren Mantel aus, wirft ihn über etwas und zieht dann sanft an einem Strick.",
	["pulls on one invisible glove, then another over it, flexing their fingers."] = "zieht einen unsichtbaren Handschuh an, dann einen zweiten darüber, und bewegt die Finger.",
	["pulls slowly on an invisible rope, then again, keeping time."] = "zieht langsam an einem unsichtbaren Seil, dann noch einmal, im Takt.",
	["pulls their coat closed and turns their face out of the firelight."] = "zieht den Mantel zu und wendet das Gesicht vom Feuerschein ab.",
	["pulls their hand back from the fire quickly."] = "zieht die Hand schnell vom Feuer zurück.",
	["pumps their arms, breathing hard, and glances back over one shoulder."] = "schwingt die Arme wie in vollem Lauf, atmet schwer und wirft einen Blick über die Schulter zurück.",
	["pumps their elbows where they sit, breathing hard."] = "schwingt im Sitzen die Ellbogen wie in vollem Lauf und atmet schwer.",
	["purses their lips and whistles two soft notes, up and down."] = "spitzt die Lippen und pfeift leise zwei Töne, rauf und runter.",
	["pushes their pack an arm's length away, hesitates, and draws it close again."] = "schiebt den Rucksack eine Armlänge von sich, zögert und zieht ihn wieder heran.",
	["raises a cup to no one in particular."] = "hebt den Becher, ohne jemand Bestimmtem zuzuprosten.",
	["raises a finger toward the dark overhead, then lets it sink."] = "hebt einen Finger zur Dunkelheit über sich und lässt ihn wieder sinken.",
	["raises a fist and brings it down slowly, as if on an unseen anvil."] = "hebt eine Faust und lässt sie langsam niedersinken, wie auf einen unsichtbaren Amboss.",
	["raises a hand flat above their own head, as if measuring."] = "hält eine Hand flach über den eigenen Kopf, wie um Maß zu nehmen.",
	["raises an eyebrow and gives the fire a slow, knowing look."] = "hebt eine Augenbraue und wirft dem Feuer einen langen, wissenden Blick zu.",
	["raises an imaginary mug toward the fire."] = "hebt einen unsichtbaren Krug in Richtung Feuer.",
	["raises an imaginary spear, sights down it, then shifts their aim a little low."] = "hebt einen unsichtbaren Speer, peilt daran entlang und zielt dann ein wenig tiefer.",
	["raises an invisible bucket a little way, holds it there, and then sets it down again."] = "hebt einen unsichtbaren Eimer ein Stück an, hält ihn dort und stellt ihn dann wieder ab.",
	["raises an invisible vial to the firelight."] = "hebt ein unsichtbares Fläschchen ins Licht des Feuers.",
	["raises an unsteady hand and sways where they sit, squinting along an invisible blade."] = "hebt eine zittrige Hand, schwankt im Sitzen und peilt blinzelnd eine unsichtbare Klinge entlang.",
	["raises both arms and sways solemnly from side to side."] = "hebt beide Arme und wiegt sich feierlich von einer Seite zur anderen.",
	["raises both fists and brings them down hard on an invisible drum, once, twice."] = "hebt beide Fäuste und lässt sie hart auf eine unsichtbare Trommel niedersausen, einmal, zweimal.",
	["raises both fists as if gripping a hilt and braces against the air."] = "hebt beide Fäuste, als umklammerten sie einen Schwertgriff, und stemmt sich gegen die Luft.",
	["raises both hands as if gripping an axe, then brings them down hard."] = "hebt beide Hände wie um eine Axt und lässt sie dann mit Wucht niederfahren.",
	["raises both hands solemnly, then winces at the memory."] = "hebt feierlich beide Hände und verzieht dann bei der Erinnerung das Gesicht.",
	["raises both palms, as if calming two arguing friends."] = "hebt beide Handflächen, wie um zwei streitende Freunde zu beruhigen.",
	["raises one arm overhead at an angle, bracing it with the other hand, and winces at each blow."] = "hebt einen Arm schräg über den Kopf, stützt ihn mit der anderen Hand und zuckt bei jedem Schlag zusammen.",
	["raises one finger to explain, thinks better of it, and lowers it slowly."] = "hebt einen Finger, um etwas zu erklären, überlegt es sich anders und senkt ihn langsam.",
	["raises one hand near the fire and studies the shadow between their fingers."] = "hält eine Hand nah ans Feuer und betrachtet den Schatten zwischen den Fingern.",
	["raises one hand solemnly, as if casting a vote."] = "hebt feierlich eine Hand, wie zur Abstimmung.",
	["raises one open hand quickly, fingers spread, and holds it there."] = "hebt rasch eine offene Hand, die Finger gespreizt, und hält sie so.",
	["raises their cup, solemnly, as if to a worthy opponent."] = "hebt feierlich den Becher, wie auf einen würdigen Gegner.",
	["rakes the coals together with a stick, saving the heat."] = "schiebt die Glut mit einem Stock zusammen, damit die Hitze bleibt.",
	["raps their knuckles three times on the ground, then waits."] = "klopft dreimal mit den Knöcheln auf den Boden und wartet.",
	["raps three times on the ground beside them, then waits, head tilted."] = "klopft dreimal neben sich auf den Boden und wartet dann mit schief gelegtem Kopf.",
	["reaches down out of habit, as if to scratch a pet behind the ear."] = "greift aus Gewohnheit nach unten, als wollte die Hand ein Tier hinterm Ohr kraulen.",
	["reaches out and gently smooths a strand of invisible hair."] = "streckt die Hand aus und streicht sanft eine unsichtbare Haarsträhne glatt.",
	["reaches up and carefully snips at something overhead with two fingers."] = "greift nach oben und schnippelt vorsichtig mit zwei Fingern an etwas über dem Kopf.",
	["reaches up, hand over hand, breathing harder with every reach."] = "greift nach oben, Hand über Hand, und atmet mit jedem Griff schwerer.",
	["rests a hand flat on their knee and looks into the coals for a while."] = "legt eine Hand flach aufs Knie und schaut eine Weile in die Glut.",
	["rests a hand on an invisible neck and pats it twice."] = "legt eine Hand auf einen unsichtbaren Hals und tätschelt ihn zweimal.",
	["rests one hand on the air, as if on the top of a low gate, then lets it fall."] = "legt eine Hand in die Luft, wie auf ein niedriges Tor, und lässt sie dann sinken.",
	["rests the hand on one knee, palm open."] = "legt die Hand aufs Knie, die Handfläche offen.",
	["rests their fingertips lightly over one pocket."] = "legt die Fingerspitzen leicht auf eine Tasche.",
	["rolls one shoulder, as if the bruise still aches."] = "lässt eine Schulter kreisen, als täte der blaue Fleck noch weh.",
	["rolls something small between finger and thumb, then flicks it away."] = "rollt etwas Kleines zwischen Daumen und Zeigefinger und schnippt es dann fort.",
	["rolls their neck and stretches, in a distinctly animal way."] = "lässt den Nacken kreisen und streckt sich, auf eine eindeutig tierische Art.",
	["rolls their shoulders, then tilts slowly into some unfelt gust."] = "lässt die Schultern kreisen und neigt sich dann langsam in eine Bö, die sonst niemand spürt.",
	["rolls up one sleeve to show an old, crescent-shaped scar."] = "krempelt einen Ärmel hoch und zeigt eine alte, sichelförmige Narbe.",
	["rubs a pinch of cold ash from the fire's edge between their fingers, and smiles."] = "zerreibt eine Prise kalter Asche vom Rand des Feuers zwischen den Fingern und lächelt.",
	["rubs a pinch of cold ash from the fire's edge between their fingers, with some satisfaction."] = "zerreibt eine Prise kalte Asche vom Rand des Feuers zwischen den Fingern, sichtlich zufrieden.",
	["rubs a thumb across their own palm, as if the handshake were still there."] = "reibt mit dem Daumen über die eigene Handfläche, als wäre der Handschlag noch da.",
	["rubs a thumb across their palm, as if wiping dirt off something small."] = "reibt mit dem Daumen über die Handfläche, wie um Erde von etwas Kleinem zu wischen.",
	["rubs a thumb and two fingers together."] = "reibt Daumen und zwei Finger aneinander.",
	["rubs a thumb in small, firm circles over one palm."] = "reibt einen Daumen in kleinen, festen Kreisen über eine Handfläche.",
	["rubs an invisible coin between finger and thumb."] = "reibt eine unsichtbare Münze zwischen Daumen und Zeigefinger.",
	["rubs both wrists slowly, as if feeling old chains."] = "reibt sich langsam beide Handgelenke, als wären dort noch alte Ketten zu spüren.",
	["rubs finger and thumb together as though testing a pinch of grit."] = "reibt Daumen und Zeigefinger aneinander, wie um eine Prise Sand zu prüfen.",
	["rubs finger and thumb together, as though testing a pinch of soil."] = "reibt Daumen und Zeigefinger aneinander, wie um eine Prise Erde zu prüfen.",
	["rubs the back of their neck, and looks down at the fire."] = "reibt sich den Nacken und blickt hinab ins Feuer.",
	["rubs the back of their neck, sheepish."] = "reibt sich verlegen den Nacken.",
	["rubs the side of one thumb slowly across their palm."] = "reibt langsam mit der Daumenkante über die Handfläche.",
	["rubs their fingers together, as if brushing away soot."] = "reibt die Finger aneinander, als klebte Ruß daran.",
	["rubs their hands together by the fire."] = "reibt sich am Feuer die Hände.",
	["rubs their jaw slowly, as if checking for stubble."] = "reibt sich langsam übers Kinn, wie auf der Suche nach Stoppeln.",
	["rubs their thumb and fingers together as though testing for dust, then stops themselves."] = "reibt Daumen und Finger aneinander, wie um nach Staub zu tasten, und hält dann jäh inne.",
	["runs a finger slowly down an invisible page, then stops."] = "fährt mit einem Finger langsam eine unsichtbare Seite hinab und hält dann inne.",
	["runs a fingertip along an imaginary seam on their sleeve."] = "fährt mit der Fingerspitze eine unsichtbare Naht am Ärmel entlang.",
	["runs a hand low through the air, near the knee, as if along an old wall."] = "fährt mit einer Hand tief durch die Luft, etwa auf Kniehöhe, wie an einer alten Mauer entlang.",
	["runs a length of old cord through their fingers, stopping at each knot."] = "lässt ein Stück alte Schnur durch die Finger gleiten und hält bei jedem Knoten inne.",
	["runs a slow hand along an invisible length of wood, feeling for the grain."] = "fährt mit der Hand langsam an einem unsichtbaren Stück Holz entlang und tastet nach der Maserung.",
	["runs a thumb along an invisible edge."] = "fährt mit dem Daumen an einer unsichtbaren Schneide entlang.",
	["runs a thumb along an old notch in their weapon."] = "fährt mit dem Daumen über eine alte Scharte in der Waffe.",
	["runs a thumb along the nicks in their blade."] = "fährt mit dem Daumen über die Scharten in der Klinge.",
	["runs a thumb over a board, then stops at something and looks closer."] = "fährt mit dem Daumen über ein Brett, stockt an etwas und schaut genauer hin.",
	["runs a thumb slowly along an imaginary edge."] = "fährt mit dem Daumen langsam an einer unsichtbaren Klinge entlang.",
	["runs one finger down an invisible page, then stops."] = "fährt mit einem Finger eine unsichtbare Seite hinunter und hält dann inne.",
	["says nothing more, and watches the black branches lean a little closer over the firelight."] = "sagt nichts mehr und sieht zu, wie sich die schwarzen Äste ein wenig näher über den Feuerschein neigen.",
	["scoops up a handful of dirt and lets it sift through their fingers."] = "schöpft eine Handvoll Erde und lässt sie durch die Finger rieseln.",
	["scoops up a handful of imaginary dirt, frowns at it, and lets it run through their fingers."] = "schöpft eine Handvoll unsichtbarer Erde, betrachtet sie stirnrunzelnd und lässt sie durch die Finger rinnen.",
	["scratches a slow line in the ashes with a stick, then adds another beneath it."] = "zieht mit einem Stock eine langsame Linie in die Asche und setzt eine zweite darunter.",
	["scratches an imaginary companion behind the ears."] = "krault einen unsichtbaren Begleiter hinter den Ohren.",
	["scuttles two fingers along an imaginary track, grinning wide."] = "lässt zwei Finger über eine unsichtbare Rennbahn krabbeln und grinst breit.",
	["sets a scrap of jerky down beside them, where an old dog might find it."] = "legt ein Stück Dörrfleisch neben sich, wo ein alter Hund es finden könnte.",
	["sets a scrap of their dinner at the edge of the firelight, and does not look to see what comes."] = "legt einen Bissen vom Abendessen an den Rand des Feuerscheins und schaut nicht hin, was kommt.",
	["sets a small stone on the ring around the fire, then a second beside it, and says no more."] = "legt einen kleinen Stein auf den Ring ums Feuer, dann einen zweiten daneben, und sagt nichts mehr.",
	["sets one shoulder low and pushes slowly forward, jaw tight."] = "senkt eine Schulter tief und drückt sich langsam vorwärts, die Zähne fest zusammengebissen.",
	["sets one thing on top of another, with great care, and sits back."] = "stapelt mit großer Sorgfalt eines auf das andere und lehnt sich zurück.",
	["sets something down with both hands and does not look up."] = "stellt etwas mit beiden Händen ab und blickt nicht auf.",
	["sets something heavy down carefully and eases themselves back with a long breath."] = "legt etwas Schweres behutsam ab und lehnt sich mit einem langen Atemzug zurück.",
	["sets the stick down and nods across the flames at {target}."] = "legt den Stock ab und nickt {target} über die Flammen hinweg zu.",
	["sets the stone by the ring of the fire, carefully, as if leaving it for someone."] = "legt den Stein behutsam an den Rand der Feuerstelle, als läge er dort für jemanden bereit.",
	["sets their two fists side by side, then opens a small gap between them."] = "hält beide Fäuste nebeneinander und lässt dann eine kleine Lücke dazwischen.",
	["sets two tin cups beside the fire and fills them both."] = "stellt zwei Blechbecher ans Feuer und füllt beide.",
	["settles lower, as though easing onto the edge of a cot."] = "lässt sich tiefer sinken, wie auf den Rand einer Pritsche.",
	["settles their weight with a grunt and starts unlacing an imaginary boot with great care."] = "lässt sich mit einem Grunzen nieder und schnürt mit großer Sorgfalt einen unsichtbaren Stiefel auf.",
	["shades their eyes and cranes their neck, squinting past the firelight."] = "beschattet die Augen, reckt den Hals und späht über den Feuerschein hinaus.",
	["shades their eyes and peers around the circle of listeners, looking increasingly worried."] = "beschattet die Augen mit der Hand und späht immer besorgter in die Runde der Zuhörer.",
	["shades their eyes with one hand and peers around the fire."] = "beschattet die Augen mit einer Hand und späht rund ums Feuer.",
	["shakes a fist at the sky, then stops to catch their breath."] = "droht dem Himmel mit der Faust und muss dann erst mal verschnaufen.",
	["shakes a fist in the air as if ringing a bell, faster and faster."] = "schwingt die Faust durch die Luft wie beim Glockenläuten, schneller und schneller.",
	["shapes a small tin in the air with both hands, then gently closes the lid."] = "formt mit beiden Händen eine kleine Dose in der Luft und schließt dann sacht den Deckel.",
	["shaves a thin curl from a small piece of wood and watches it fall."] = "schält einen dünnen Span von einem kleinen Stück Holz und sieht ihm beim Fallen zu.",
	["shields a tiny flame with one hand."] = "schirmt mit einer Hand eine winzige Flamme ab.",
	["shifts an invisible weight on one shoulder and rubs the spot with a grimace."] = "verlagert ein unsichtbares Gewicht auf der Schulter und reibt sich mit verzogenem Gesicht die Stelle.",
	["shifts back against nothing at all and slowly, blissfully, rubs their back from side to side."] = "lehnt sich gegen das Nichts zurück und schubbert langsam und selig den Rücken hin und her.",
	["shifts over a little, leaving space by the fire as if for someone else."] = "rückt ein wenig zur Seite und lässt am Feuer Platz, als wäre er für jemanden bestimmt.",
	["shifts over to one side, leaving a space beside them."] = "rückt zur Seite und lässt neben sich einen Platz frei.",
	["shivers and pulls their cloak a little tighter."] = "schaudert und zieht den Umhang etwas enger.",
	["shivers."] = "erschaudert.",
	["shoves at the air with both hands, wincing with each push."] = "stemmt sich mit beiden Händen gegen die Luft und verzieht bei jedem Stoß das Gesicht.",
	["shoves both hands sideways through the air, hard."] = "stößt beide Hände kräftig seitwärts durch die Luft.",
	["shoves hard at the air with both hands."] = "stößt mit beiden Händen kräftig gegen die Luft.",
	["shoves something round forward with both hands, then grips the air tight."] = "schiebt mit beiden Händen etwas Rundes nach vorn und krallt sich dann in der Luft fest.",
	["sighs and shakes their head at the fire."] = "seufzt und schüttelt den Kopf in Richtung Feuer.",
	["sighs."] = "seufzt.",
	["sinks down slowly until their chin is tucked, eyes wide and darting."] = "sinkt langsam tiefer, bis das Kinn verschwunden ist, und lässt die weit aufgerissenen Augen hin und her huschen.",
	["sinks lower where they sit, with the long sigh of someone easing into a tub."] = "sinkt tiefer in sich zusammen, mit dem langen Seufzer von jemandem, der sich in eine Wanne gleiten lässt.",
	["sinks slowly downward with a look of deep calm, cheeks not puffed at all."] = "sinkt langsam nach unten, tiefe Ruhe im Gesicht, die Backen kein bisschen aufgeblasen.",
	["sits back from the fire and lets the story settle."] = "lehnt sich vom Feuer zurück und lässt die Geschichte nachklingen.",
	["sits perfectly still, one arm still raised from the throw."] = "sitzt völlig reglos da, einen Arm noch vom Wurf erhoben.",
	["sits up straight and raises one hand, palm out, like someone refusing a request."] = "setzt sich kerzengerade auf und hebt eine Hand, die Handfläche nach vorn, wie jemand, der eine Bitte abschlägt.",
	["sits up suddenly and listens, one hand raised for silence."] = "setzt sich plötzlich auf und lauscht, eine Hand zum Schweigen erhoben.",
	["sits up very slowly, arms stiff at their sides, staring ahead."] = "richtet sich ganz langsam auf, die Arme steif an den Seiten, und starrt geradeaus.",
	["sits up very straight, eyes fixed on something far past the firelight."] = "sitzt kerzengerade da, den Blick auf etwas weit jenseits des Feuerscheins gerichtet.",
	["sits up very straight, folds their arms, and closes their eyes."] = "setzt sich kerzengerade hin, verschränkt die Arme und schließt die Augen.",
	["sits up with their chin level and shoulders still, as if a brimming bowl rested on their head."] = "setzt sich gerade hin, das Kinn waagerecht, die Schultern ruhig, als stünde eine randvolle Schale auf dem Kopf.",
	["sits very still, the firelight moving over a face that does not."] = "sitzt ganz still, der Feuerschein spielt über ein Gesicht, das sich nicht bewegt.",
	["sketches a huge curve in the air with one finger."] = "malt mit einem Finger einen riesigen Bogen in die Luft.",
	["sketches a weary sign of blessing in the air, like someone swatting a fly."] = "zeichnet müde ein Segenszeichen in die Luft, wie jemand, der eine Fliege verscheucht.",
	["slaps at their neck, then their arm, then flails at the empty air."] = "schlägt sich in den Nacken, dann auf den Arm und fuchtelt schließlich wild in der leeren Luft herum.",
	["slashes left, slashes right, then throws an arm up against an imaginary blow."] = "schlägt nach links, schlägt nach rechts und reißt dann einen Arm gegen einen unsichtbaren Hieb hoch.",
	["slides half of an invisible stack of coins toward themselves, leaving the rest."] = "schiebt die Hälfte eines unsichtbaren Münzstapels zu sich herüber und lässt den Rest liegen.",
	["slides the arrow back into the quiver, feather up, where it's easy to find."] = "schiebt den Pfeil zurück in den Köcher, die Feder nach oben, damit er leicht zu finden ist.",
	["slides three invisible cups around on the ground, fast."] = "schiebt flink drei unsichtbare Becher über den Boden.",
	["slowly lowers their hands and wipes them on their knees."] = "senkt langsam die Hände und wischt sie an den Knien ab.",
	["slowly raises their eyes upward, then lowers them again."] = "hebt langsam den Blick nach oben und senkt ihn dann wieder.",
	["slowly tips their shoulders to the wrong side and holds there, looking uneasy."] = "neigt die Schultern langsam zur falschen Seite und verharrt so, sichtlich unbehaglich.",
	["slumps sideways with their tongue out and eyes rolled up, perfectly still."] = "sackt zur Seite, die Zunge heraus, die Augen verdreht, völlig reglos.",
	["smiles a little into their cup and lets the joke stand."] = "lächelt ein wenig in den Becher und lässt den Witz stehen.",
	["smiles and lays a hand flat over their heart."] = "lächelt und legt eine Hand flach aufs Herz.",
	["smiles at the fire."] = "lächelt ins Feuer.",
	["smiles at {target} a little too brightly."] = "lächelt {target} ein wenig zu strahlend an.",
	["smiles down at a folded scrap of paper they clearly cannot read."] = "lächelt auf einen gefalteten Zettel hinab und kann offensichtlich kein Wort davon lesen.",
	["smiles into the fire, and doesn't say anything for a moment."] = "lächelt ins Feuer und sagt eine Weile nichts.",
	["smiles into the fire."] = "lächelt ins Feuer.",
	["smiles thinly and looks away, shifting so the firelight doesn't quite reach their face."] = "lächelt dünn und schaut weg, rückt so, dass der Feuerschein das Gesicht nicht ganz erreicht.",
	["smiles to themselves."] = "lächelt still vor sich hin.",
	["smooths a fold of cloth across one knee, slowly, and leaves their hand resting on it."] = "streicht langsam eine Stofffalte über einem Knie glatt und lässt die Hand darauf liegen.",
	["smooths a patch of ground flat with the palm of one hand."] = "streicht mit einer Handfläche ein Stück Boden glatt.",
	["smooths down the front of their shirt with a small, pleased smile."] = "streicht sich mit einem kleinen, zufriedenen Lächeln das Hemd vorne glatt.",
	["smooths down their hair, looking faintly worried."] = "streicht sich die Haare glatt und sieht dabei leicht besorgt aus.",
	["snaps a thorny branch for the fire, sucks a pricked thumb, and nods as if the point were proved."] = "bricht einen dornigen Zweig fürs Feuer, lutscht am gestochenen Daumen und nickt, als wäre damit alles bewiesen.",
	["snaps their fingers, looks pleased, and then lets the smile slowly fade."] = "schnippt mit den Fingern, sieht zufrieden aus und lässt das Lächeln dann langsam verblassen.",
	["snatches at something on the ground, then hunches low with an arm over their head."] = "grapscht nach etwas am Boden und duckt sich dann tief, einen Arm über dem Kopf.",
	["snatches up a stick and scrawls furiously in the ashes, as if it were a stub of chalk."] = "schnappt sich einen Stock und kritzelt wild in die Asche, als wäre er ein Stück Kreide.",
	["sneezes enormously, then looks around in horror."] = "niest gewaltig und blickt sich dann entsetzt um.",
	["sniffs one wrist, winces, and wipes it on their knee."] = "schnuppert an einem Handgelenk, verzieht das Gesicht und wischt es am Knie ab.",
	["sniffs the air once, then stops, and presses their lips together."] = "schnuppert einmal in die Luft, hält dann inne und presst die Lippen aufeinander.",
	["sniffs the air, then slowly turns their head to look behind them."] = "schnuppert in die Luft und dreht dann langsam den Kopf, um hinter sich zu schauen.",
	["spreads both hands, palms up, and lifts them slowly."] = "breitet beide Hände aus, die Handflächen nach oben, und hebt sie langsam.",
	["spreads their arms wide and hisses, then looks faintly embarrassed."] = "breitet die Arme weit aus und zischt, und wirkt dann leicht verlegen.",
	["spreads their arms wide and wobbles, trying to keep their balance."] = "breitet die Arme weit aus und wackelt, um das Gleichgewicht zu halten.",
	["spreads their hands in a gesture of complete and final innocence."] = "breitet die Hände zu einer Geste vollkommener, endgültiger Unschuld aus.",
	["spreads their hands wider and wider apart, as if measuring a raptor that keeps growing."] = "breitet die Hände weiter und weiter auseinander, wie um einen Raptor zu messen, der immer weiter wächst.",
	["spreads their hands wider and wider, then slowly draws them back into their lap."] = "breitet die Hände weiter und weiter aus und legt sie dann langsam wieder in den Schoß.",
	["spreads their hands, still honestly troubled by the question."] = "breitet die Hände aus, von der Frage noch immer ehrlich beunruhigt.",
	["squares their shoulders and raises one arm, as if a shield still hung from it."] = "strafft die Schultern und hebt einen Arm, als hinge noch ein Schild daran.",
	["squints across the fire at {target}, tilting their head one way and then the other."] = "blinzelt über das Feuer zu {target} hinüber und legt den Kopf erst auf die eine, dann auf die andere Seite.",
	["squints along the rim of an invisible mug, deeply unconvinced."] = "peilt über den Rand eines unsichtbaren Kruges und ist kein bisschen überzeugt.",
	["squints and rubs their temples with both hands."] = "kneift die Augen zusammen und reibt sich mit beiden Händen die Schläfen.",
	["squints at the coals with a smith's eye, plainly unimpressed, then grins."] = "beäugt die Glut mit Schmiedeblick, sichtlich unbeeindruckt, und grinst dann.",
	["stares at nothing in particular for a while before speaking."] = "starrt eine Weile ins Leere, bevor die Worte kommen.",
	["stares blankly ahead, imitating a whole room of unamused faces."] = "starrt ausdruckslos geradeaus und ahmt einen ganzen Saal voll unbeeindruckter Gesichter nach.",
	["stares down at an invisible bowl, a spoon halfway to their mouth."] = "starrt auf eine unsichtbare Schüssel, den Löffel auf halbem Weg zum Mund.",
	["stares hard into the dark beyond the fire, without blinking."] = "starrt angestrengt in die Dunkelheit hinter dem Feuer, ohne zu blinzeln.",
	["stares into the coals for a long moment."] = "starrt lange schweigend in die Glut.",
	["stares into the fire a while before looking up again."] = "starrt eine Weile ins Feuer, bevor der Blick sich wieder hebt.",
	["stares into the fire, as if it might have an answer of its own."] = "starrt ins Feuer, als hätte es vielleicht eine eigene Antwort.",
	["stares into the flames and doesn't blink for a while."] = "starrt in die Flammen und blinzelt eine ganze Weile nicht.",
	["stares into the sullen, smoking fire, and takes their time before going on."] = "starrt ins trübe, qualmende Feuer und lässt sich Zeit, bevor es weitergeht.",
	["stays very still, head cocked toward the dark, as though for two soft notes."] = "bleibt ganz still, den Kopf zur Dunkelheit geneigt, wie um auf zwei leise Töne zu horchen.",
	["steps their hands forward through the air, one flat palm after the other, testing each one."] = "setzt in der Luft eine flache Hand vor die andere und prüft jedes Mal den Halt.",
	["stirs an invisible pot with growing effort, then stops, the spoon stuck fast."] = "rührt mit wachsender Mühe in einem unsichtbaren Topf und hört dann auf, der Löffel steckt fest.",
	["stirs the coals with a stick, lips still moving."] = "stochert mit einem Stock in der Glut, die Lippen bewegen sich noch immer.",
	["stops fiddling with a small gear and just holds it."] = "hört auf, an einem kleinen Zahnrad herumzufummeln, und hält es einfach nur fest.",
	["stops moving entirely, barely breathing, eyes fixed on the dark."] = "hält vollkommen still, atmet kaum, den Blick fest ins Dunkel gerichtet.",
	["stops talking and holds very still for a moment."] = "hört auf zu reden und hält einen Moment ganz still.",
	["stops talking and looks just past {target}'s shoulder."] = "hört auf zu reden und blickt knapp an der Schulter von {target} vorbei.",
	["straightens their back, chin high, one hand flat over the heart."] = "richtet sich kerzengerade auf, das Kinn hoch, eine Hand flach auf dem Herzen.",
	["straightens their collar and attempts an expression of great respectability."] = "rückt den Kragen zurecht und versucht, sehr ehrbar dreinzuschauen.",
	["straightens their own collar, then straightens it again, more carefully."] = "rückt den eigenen Kragen zurecht und dann noch einmal, sorgfältiger.",
	["stretches and settles back, ready for sleep."] = "streckt sich und macht es sich zum Schlafen bequem.",
	["stretches their hands toward a fire, then slowly draws them back."] = "streckt die Hände nach einem Feuer aus und zieht sie dann langsam zurück.",
	["stretches their mouth into a stiff, uncertain grin, then lets it drop."] = "zieht den Mund zu einem steifen, unsicheren Grinsen und lässt es wieder fallen.",
	["stretches their shoulders and lets out a slow, contented breath."] = "streckt die Schultern und atmet langsam und zufrieden aus.",
	["strikes their hands together sharply, then shields their eyes from a sudden blaze."] = "schlägt die Hände hart zusammen und schirmt dann die Augen gegen eine jähe Flamme ab.",
	["studies {target} across the fire with a thoughtful frown."] = "mustert {target} über das Feuer hinweg mit nachdenklich gerunzelter Stirn.",
	["sways a little where they sit, as if to slow music."] = "wiegt sich im Sitzen ein wenig, wie zu langsamer Musik.",
	["sways gently where they sit, wearing a look of perfect trust."] = "schwankt sanft im Sitzen, mit einem Ausdruck vollkommenen Vertrauens.",
	["swings an arm wildly at nothing, falling just short, then lets it drop."] = "schlägt wild mit dem Arm durch die Luft, verfehlt knapp und lässt ihn dann sinken.",
	["swings an imaginary pick, slowly, then rubs the small of their back with a groan."] = "schwingt langsam eine unsichtbare Spitzhacke und reibt sich dann stöhnend das Kreuz.",
	["swings an invisible tool down onto the ground."] = "lässt ein unsichtbares Werkzeug auf den Boden niedersausen.",
	["swings one arm in a wide loop over their head and lets something fly."] = "schwingt einen Arm in weitem Bogen über dem Kopf und lässt etwas fliegen.",
	["takes a bite of the apple, chews, and pitches the core into the fire, where it hisses."] = "beißt in den Apfel, kaut und wirft das Kerngehäuse ins Feuer, wo es zischt.",
	["takes a sip from their cup and makes a sour face."] = "nimmt einen Schluck aus dem Becher und verzieht sauer das Gesicht.",
	["takes a split log from the firewood, knocks twice on it, and listens to the sound."] = "nimmt ein gespaltenes Scheit vom Feuerholz, klopft zweimal darauf und lauscht dem Klang.",
	["takes a stub of charcoal and adds one more small mark."] = "nimmt einen Stummel Kohle und setzt noch ein kleines Kreuz dazu.",
	["takes a worn, much-folded letter from a pouch and smooths it out."] = "holt einen abgegriffenen, oft gefalteten Brief aus einem Beutel und streicht ihn glatt.",
	["takes off one boot, turns it over, and watches a thin stream of sand patter into the fire."] = "zieht einen Stiefel aus, dreht ihn um und sieht zu, wie ein dünnes Rinnsal Sand ins Feuer rieselt.",
	["takes out a small stoppered jar and tilts it toward the light."] = "holt ein kleines verkorktes Glas hervor und hält es schräg ins Licht.",
	["takes something small from a pocket, looks at it, and puts it carefully away again."] = "holt etwas Kleines aus einer Tasche, betrachtet es und steckt es vorsichtig wieder weg.",
	["taps a finger against their chin."] = "tippt sich mit einem Finger ans Kinn.",
	["taps a fingernail once against the rim of a cup, then listens."] = "tippt einmal mit dem Fingernagel gegen den Rand eines Bechers und lauscht.",
	["taps a knuckle gently against an invisible stone, and tilts their head as if listening."] = "klopft sacht mit dem Fingerknöchel an einen unsichtbaren Stein und neigt lauschend den Kopf.",
	["taps a slow rhythm on their own knee with both hands, eyes closed."] = "klopft mit beiden Händen einen langsamen Takt auf das Knie, die Augen geschlossen.",
	["taps a small imaginary gavel, then flinches at the sound."] = "klopft mit einem kleinen unsichtbaren Hämmerchen auf und zuckt beim Geräusch zusammen.",
	["taps one knuckle against a piece of firewood and listens."] = "klopft mit einem Fingerknöchel gegen ein Stück Feuerholz und lauscht.",
	["taps out a slow rhythm with one finger: long, short, short."] = "klopft mit einem Finger einen langsamen Rhythmus: lang, kurz, kurz.",
	["taps the side of their cup to get everyone's attention."] = "klopft an den Becher, damit alle herschauen.",
	["taps the side of their cup, slow and even, like someone counting."] = "klopft langsam und gleichmäßig an den Becher, wie jemand, der zählt.",
	["taps the side of their nose twice."] = "tippt sich zweimal an die Nase.",
	["taps their chin, thinking, then spreads their hands helplessly."] = "tippt sich nachdenklich ans Kinn und breitet dann ratlos die Hände aus.",
	["taps twice on something unseen, then quickly pulls their hand away."] = "klopft zweimal auf etwas Unsichtbares und zieht die Hand dann schnell zurück.",
	["taps two fingers against their chest, where a badge might have hung."] = "tippt sich mit zwei Fingern auf die Brust, wo einmal ein Abzeichen gehangen haben könnte.",
	["taps two fingers slowly against their temple."] = "tippt sich langsam mit zwei Fingern an die Schläfe.",
	["tears a piece of bread in two, looking at it thoughtfully."] = "bricht ein Stück Brot entzwei und betrachtet es nachdenklich.",
	["tears an invisible strip of meat in two and offers half across a fire."] = "reißt einen unsichtbaren Streifen Fleisch entzwei und reicht eine Hälfte über ein Feuer.",
	["tests a knot with both hands, then tests it again."] = "prüft einen Knoten mit beiden Händen und prüft ihn dann noch einmal.",
	["the first thing you'll mine when you're new to the town. What am I?"] = "ich bin das Erste, was ihr abbaut, gleich am Anfang. Was bin ich?",
	["the gold, and then I'll carry you over the ground. What am I?"] = "dann bringt ihr das Gold, und ich darf für euch rennen. Was bin ich?",
	["the whole city asks if they've heard about you. What am I?"] = "und in der ganzen Stadt wird nur noch von mir gesprochen. Was bin ich?",
	["then rise with my help on a borrowed breath. What am I?"] = "dann hebt ihn mein geliehener Atem aus der Not. Was bin ich?",
	["throws both arms out as if skidding to a stop, and stares down in horror."] = "reißt beide Arme zur Seite, wie um schlitternd zum Stehen zu kommen, und starrt entsetzt nach unten.",
	["throws both arms up as if in front of a roaring crowd."] = "reißt beide Arme hoch wie vor einer tosenden Menge.",
	["throws one arm over their face and leans hard into nothing, gritting their teeth."] = "wirft einen Arm vors Gesicht und stemmt sich mit zusammengebissenen Zähnen gegen das Nichts.",
	["throws themselves sideways with a great splash of both hands."] = "wirft sich mit einem großen Platschen beider Hände zur Seite.",
	["throws up their hands and laughs at the fire."] = "wirft die Hände hoch und lacht ins Feuer.",
	["thumps a fist against their own chest and listens to the sound."] = "klopft mit der Faust auf die eigene Brust und lauscht dem Klang.",
	["ties a neat knot in a bit of string without looking, then pulls it loose."] = "knüpft, ohne hinzusehen, einen sauberen Knoten in ein Stück Schnur und zieht ihn dann wieder auf.",
	["ties the knot again, and this time leaves it tied."] = "knüpft den Knoten noch einmal und lässt ihn diesmal, wie er ist.",
	["tilts an invisible cup slowly sideways and watches it with great suspicion."] = "kippt einen unsichtbaren Becher langsam zur Seite und beäugt ihn voller Misstrauen.",
	["tilts slowly to one side, holds it for a moment, then straightens with a sigh."] = "neigt sich langsam zur Seite, verharrt kurz und richtet sich dann seufzend wieder auf.",
	["tilts their face to the sky with their eyes closed and their palms up."] = "hebt das Gesicht zum Himmel, die Augen geschlossen, die Handflächen nach oben.",
	["tilts their head and leans it against the empty air, as though resting one ear on something huge."] = "neigt den Kopf und lehnt ihn gegen die leere Luft, als ruhte ein Ohr an etwas Riesigem.",
	["tilts their head back and stares at the sky."] = "legt den Kopf in den Nacken und starrt in den Himmel.",
	["tilts their head back, as though looking up into tall branches."] = "legt den Kopf in den Nacken und blickt hinauf, als wären dort hohe Äste.",
	["tilts their head sideways and clears their throat with exaggerated courtesy."] = "legt den Kopf schief und räuspert sich übertrieben höflich.",
	["tilts their head sideways and tugs gently at nothing, with growing concern."] = "legt den Kopf schief und zieht sanft an etwas Unsichtbarem, zunehmend besorgt.",
	["tilts their head slightly, as though hearing something faint."] = "neigt den Kopf ein wenig, wie beim Lauschen auf einen fernen, leisen Laut.",
	["tilts their head toward the dark and attempts an innocent expression."] = "neigt den Kopf zur Dunkelheit hin und versucht, unschuldig dreinzuschauen.",
	["tilts their head toward the ground and listens, not moving at all."] = "neigt den Kopf zum Boden und lauscht, ohne sich zu rühren.",
	["tilts their head, as though listening for rain on a roof far from here."] = "neigt den Kopf, wie um auf Regen zu lauschen, der weit weg auf ein Dach fällt.",
	["tilts their head, listening, and holds up one finger for silence."] = "neigt lauschend den Kopf und hebt einen Finger für Stille.",
	["tilts their head, wearing a look of gentle confusion."] = "legt den Kopf schief, mit einem Ausdruck sanfter Verwirrung.",
	["tips a little from their waterskin onto the ground beside them, and says nothing more."] = "gießt ein wenig aus dem Wasserschlauch neben sich auf den Boden und sagt nichts mehr.",
	["tips an imaginary hat toward the darkness."] = "lüftet einen unsichtbaren Hut in Richtung Dunkelheit.",
	["tips their head back and goes quiet, gazing straight up."] = "legt den Kopf in den Nacken und wird still, den Blick gerade nach oben gerichtet.",
	["tosses a dry twig into the flames and watches how quickly it is gone."] = "wirft einen trockenen Zweig in die Flammen und sieht zu, wie schnell er vergeht.",
	["tosses a small bone into the fire with great bitterness."] = "wirft voller Bitterkeit einen kleinen Knochen ins Feuer.",
	["tosses an apple up and catches it without looking."] = "wirft einen Apfel hoch und fängt ihn, ohne hinzusehen.",
	["touches one finger to an imaginary jug and frosts it with tremendous solemnity."] = "berührt mit einem Finger einen unsichtbaren Krug und überzieht ihn ungeheuer feierlich mit Frost.",
	["touches their rolled bedding, then draws their hands back toward the warmth."] = "berührt das zusammengerollte Bettzeug und zieht dann die Hände zurück zur Wärme.",
	["touches two fingers to the ground, then to their heart."] = "berührt mit zwei Fingern den Boden, dann das eigene Herz.",
	["traces a few letters in the dirt with one finger, then wipes them away."] = "malt mit einem Finger ein paar Buchstaben in die Erde und wischt sie wieder weg.",
	["traces a few slow letters in the air with one finger."] = "zeichnet mit einem Finger langsam ein paar Buchstaben in die Luft.",
	["traces a line across an invisible page, lips moving silently."] = "fährt mit dem Finger eine Zeile auf einer unsichtbaren Seite entlang, die Lippen bewegen sich lautlos.",
	["traces a line across their palm with one finger, then taps it with a knuckle."] = "zieht mit einem Finger eine Linie über die Handfläche und klopft dann mit dem Knöchel darauf.",
	["traces a little patch shape in the air and goes still."] = "zeichnet die Form eines kleinen Flickens in die Luft und hält dann still inne.",
	["traces a long, winding shape across the sky with one finger."] = "malt mit einem Finger eine lange, gewundene Form in den Himmel.",
	["tucks something small into an invisible crack, glancing left and right."] = "schiebt etwas Kleines in einen unsichtbaren Spalt und schaut dabei nach links und rechts.",
	["tucks the cord away and looks out past the firelight."] = "steckt die Schnur weg und blickt in die Dunkelheit jenseits des Feuerscheins.",
	["tucks the folded paper into a pocket, close to their heart."] = "steckt das gefaltete Papier in eine Tasche, nah am Herzen.",
	["tucks the invisible button into a pocket and pats it."] = "steckt den unsichtbaren Knopf in eine Tasche und klopft sanft darauf.",
	["tucks the jar away again, gently, and pats the pocket twice."] = "steckt das Glas behutsam wieder weg und klopft zweimal auf die Tasche.",
	["tucks their elbows in tight and works both hands in a small space, feeling for something."] = "zieht die Ellbogen eng an und tastet mit beiden Händen auf engem Raum nach etwas.",
	["tugs at a lead rope, then lets it go slack."] = "zupft an einem Führstrick und lässt ihn dann locker.",
	["tugs at their sleeve and checks the stitching, as if for the hundredth time."] = "zupft am Ärmel und prüft die Naht, wohl zum hundertsten Mal.",
	["turns a cup slowly in their hands, not drinking."] = "dreht einen Becher langsam in den Händen, ohne zu trinken.",
	["turns a flat stone over in their fingers, as if looking for water to skip it on."] = "dreht einen flachen Stein zwischen den Fingern, als fehle nur noch Wasser, um ihn springen zu lassen.",
	["turns a folded paper over in their hands without opening it."] = "dreht ein gefaltetes Papier in den Händen, ohne es zu öffnen.",
	["turns a pebble over and sets it down without a sound."] = "dreht einen Kiesel um und legt ihn lautlos wieder ab.",
	["turns a small stone in their fingers, looking over at {target}."] = "dreht einen kleinen Stein zwischen den Fingern und blickt zu {target} hinüber.",
	["turns a small, invisible package over in their hands."] = "dreht ein kleines, unsichtbares Päckchen in den Händen.",
	["turns a smooth gray pebble over in their fingers."] = "dreht einen glatten grauen Kiesel zwischen den Fingern.",
	["turns a stick over in the coals and does not look up."] = "dreht einen Stock in der Glut und schaut nicht auf.",
	["turns an invisible knot over in their fingers, slowly, examining it."] = "dreht langsam einen unsichtbaren Knoten zwischen den Fingern und begutachtet ihn.",
	["turns an invisible page, slowly, and runs a finger down it."] = "blättert langsam eine unsichtbare Seite um und fährt mit dem Finger daran hinab.",
	["turns an invisible page, slowly, then stops and does not turn the next one."] = "blättert langsam eine unsichtbare Seite um, hält dann inne und blättert die nächste nicht um.",
	["turns invisible pages, slowly, one at a time."] = "blättert langsam unsichtbare Seiten um, eine nach der anderen.",
	["turns one hand over slowly, as if holding something small and bright."] = "dreht langsam eine Hand um, als läge etwas Kleines, Glänzendes darin.",
	["turns one hand over slowly, palm down, and lays it flat."] = "dreht eine Hand langsam um, die Fläche nach unten, und legt sie flach hin.",
	["turns one hand palm up, then palm down, and stares at it."] = "dreht eine Hand mit der Fläche nach oben, dann nach unten, und starrt sie an.",
	["turns one open hand toward the other, leaving a little space between them."] = "dreht eine offene Hand zur anderen und lässt ein wenig Abstand dazwischen.",
	["turns one palm over and studies it for a while."] = "dreht eine Handfläche nach oben und betrachtet sie eine Weile.",
	["turns one palm upward as though weighing a leaf, then closes their fingers."] = "dreht eine Handfläche nach oben, wie um ein Blatt zu wiegen, und schließt dann die Finger.",
	["turns out one empty pocket, then the other, and sighs."] = "stülpt eine leere Tasche nach außen, dann die andere, und seufzt.",
	["turns over something small on the ground with one finger, and watches it crawl away."] = "dreht mit einem Finger etwas Kleines am Boden um und sieht zu, wie es davonkrabbelt.",
	["turns partway from the fire, then stops and glances back over one shoulder into the dark."] = "wendet sich halb vom Feuer ab, hält dann inne und blickt über die Schulter zurück ins Dunkel.",
	["turns the blade so the firelight slides along its edge, and looks at it for a while."] = "dreht die Klinge, sodass der Feuerschein über die Schneide gleitet, und betrachtet sie eine Weile.",
	["turns the invisible letter around and holds it out so the writing faces {target}."] = "dreht den unsichtbaren Brief um und hält ihn so hin, dass die Schrift zu {target} zeigt.",
	["turns the wood to the firelight, then takes off another curl and flicks it into the flames."] = "dreht das Holz ins Feuerlicht, schält noch einen Span ab und schnippt ihn in die Flammen.",
	["turns their face away and hunches their shoulders against a blast of wind."] = "wendet das Gesicht ab und zieht die Schultern gegen einen Windstoß hoch.",
	["turns their face beyond the firelight and pauses as though an answer is still owed."] = "wendet das Gesicht ins Dunkel jenseits des Feuerscheins und hält inne, als stünde dort noch eine Antwort aus.",
	["turns their face up, as if into a strong wind, and speaks a few silent words."] = "hebt das Gesicht, wie in einen starken Wind, und spricht lautlos ein paar Worte.",
	["turns their head by slow degrees until they're looking over one shoulder."] = "dreht den Kopf ganz allmählich, bis der Blick über die Schulter geht.",
	["turns their head to the side and stares with one unblinking eye."] = "dreht den Kopf zur Seite und starrt mit einem einzigen Auge, ohne zu blinzeln.",
	["turns their head toward the empty air beside them, and holds very still."] = "dreht den Kopf zur leeren Luft neben sich und hält ganz still.",
	["turns to {target} and opens one hand, palm up."] = "wendet sich {target} zu und öffnet eine Hand, die Handfläche nach oben.",
	["turns to {target}, speaking more softly now."] = "wendet sich {target} zu und spricht jetzt leiser.",
	["twirls one finger in a tight little circle, then points sharply."] = "dreht einen Finger in einem engen kleinen Kreis und zeigt dann ruckartig nach vorn.",
	["twists an invisible handful of grass together and ties it off with care."] = "dreht eine unsichtbare Handvoll Gras zusammen und knotet sie sorgfältig ab.",
	["twists one fist slowly, as if turning a stiff post in the ground."] = "dreht langsam eine Faust, wie um einen festsitzenden Pfahl im Boden zu bewegen.",
	["twists their whole body and yanks hard on a strap."] = "verdreht den ganzen Körper und reißt heftig an einem Riemen.",
	["twitches their nose and jerks their head around, wide-eyed, at nothing."] = "zuckt mit der Nase und reißt den Kopf mit großen Augen herum, nach gar nichts.",
	["unfolds a creased map and smooths it flat across one knee."] = "faltet eine zerknitterte Karte auf und streicht sie auf dem Knie glatt.",
	["unfolds a scrap of paper and holds it up for all to admire."] = "faltet einen Fetzen Papier auseinander und hält ihn hoch, damit alle ihn bewundern können.",
	["unfolds an invisible stool with great pride and pats the top of it."] = "klappt mit großem Stolz einen unsichtbaren Hocker auf und tätschelt die Sitzfläche.",
	["unrolls a map and smooths it flat with both hands."] = "rollt eine Karte aus und streicht sie mit beiden Händen glatt.",
	["wags a finger across the fire at {target}."] = "droht {target} über das Feuer hinweg mit dem Finger.",
	["waits while a log settles in the fire with a low thud, and does not seem to like the sound."] = "wartet, bis ein Scheit mit dumpfem Poltern im Feuer zusammensackt, und scheint das Geräusch nicht zu mögen.",
	["walks two fingers briskly off the edge of one knee, then winces all the way down."] = "lässt zwei Finger flott über die Kante eines Knies laufen und verzieht dann den ganzen Weg nach unten das Gesicht.",
	["watches a log settle in the fire and does not look up for a moment."] = "sieht zu, wie ein Scheit im Feuer zusammensackt, und blickt eine Weile nicht auf.",
	["watches a log settle in the fire and does not speak again."] = "sieht zu, wie ein Scheit im Feuer zusammensackt, und spricht nicht mehr.",
	["watches a slow ripple of heat cross the coals, and lets it fade."] = "sieht zu, wie eine träge Hitzewelle über die Glut zieht, und lässt sie verebben.",
	["watches one spark circle up above the flames, around and around, until it winks out."] = "sieht einem Funken nach, der über den Flammen aufsteigt und kreist, immer im Kreis, bis er verglimmt.",
	["watches something roll slowly past, following it with one pointing finger."] = "sieht etwas langsam vorbeirollen und folgt ihm mit ausgestrecktem Zeigefinger.",
	["watches the fire for a while, the way one might watch a lit window from outside."] = "schaut eine Weile ins Feuer, so wie man von draußen in ein erleuchtetes Fenster schaut.",
	["watches the smoke climb as it might from a chimney, and is the first to look away."] = "sieht dem Rauch nach, der aufsteigt wie aus einem Schornstein, und schaut vor allen anderen weg.",
	["watches the smoke drift off into the dark for a long while."] = "sieht lange zu, wie der Rauch ins Dunkel davonzieht.",
	["watches the smoke drift toward the listeners, scowls, and waves it back."] = "sieht den Rauch zu den Zuhörern treiben, verzieht das Gesicht und wedelt ihn zurück.",
	["watches the smoke lean one way, then the other, and nods as if it had spoken."] = "sieht zu, wie sich der Rauch erst in die eine, dann in die andere Richtung neigt, und nickt, als hätte er gesprochen.",
	["watches the space behind {target} for a long, slow moment, then looks back to the flames."] = "beobachtet einen langen, zähen Moment den Platz hinter {target} und blickt dann wieder in die Flammen.",
	["watches the sparks climb until the last one goes out."] = "sieht den Funken nach, wie sie aufsteigen, bis der letzte erlischt.",
	["watches the sparks go up into the dark and lets the moment hang."] = "sieht den Funken nach, die ins Dunkel steigen, und lässt den Moment wirken.",
	["watches the sparks lift off the fire and drift away into the dark, one by one."] = "sieht zu, wie die Funken vom Feuer aufsteigen und einer nach dem anderen in die Dunkelheit treiben.",
	["watches which way the smoke leans, and does not remark on it."] = "beobachtet, wohin sich der Rauch neigt, und sagt nichts dazu.",
	["waves a hand in front of their face and coughs politely."] = "wedelt mit der Hand vor dem Gesicht herum und hustet höflich.",
	["waves a hand in front of their nose."] = "wedelt sich mit der Hand vor der Nase herum.",
	["weighs the seed over the flames for a moment, then closes their fingers around it and puts it away."] = "wiegt den Samen einen Moment über den Flammen, schließt dann die Finger darum und steckt ihn weg.",
	["wets a finger, holds it up, and slowly turns to face the other way."] = "leckt einen Finger an, hält ihn hoch und dreht sich langsam in die andere Richtung.",
	["whips an invisible rope around something twice and leans back hard with both hands."] = "schlingt ein unsichtbares Seil zweimal um etwas und lehnt sich mit beiden Händen kräftig zurück.",
	["wiggles two fingers at the fire, and the flames happen to give a small, weary dance."] = "wackelt mit zwei Fingern zum Feuer hin, und die Flammen tanzen zufällig ein kleines, müdes Tänzchen.",
	["winces at the memory, then laughs quietly to themselves."] = "verzieht bei der Erinnerung das Gesicht und lacht dann leise in sich hinein.",
	["winds up and throws something hard and high, then holds very still, watching."] = "holt aus, wirft etwas kraftvoll und hoch und erstarrt dann, den Blick hinterher.",
	["wipes the last circle out of the ashes with one fingertip."] = "wischt mit einer Fingerspitze den letzten Kreis aus der Asche.",
	["wipes their hands slowly on their knees, as if they can't quite get them clean."] = "wischt sich langsam die Hände an den Knien ab, als würden sie einfach nicht sauber.",
	["wraps both hands around their cup with one thumb hooked over the rim, and looks at it."] = "legt beide Hände um den Becher, einen Daumen über den Rand gehakt, und betrachtet ihn.",
	["wraps one hand slowly around the other."] = "legt langsam eine Hand um die andere.",
	["wrenches an invisible rail free with both hands and drives it forward and down."] = "reißt mit beiden Händen eine unsichtbare Latte los und rammt sie nach vorn und unten.",
	["wrings out the end of their sleeve and looks at it without hope."] = "wringt den Ärmelzipfel aus und betrachtet ihn ohne jede Hoffnung.",
	["wrings out the hem of one sleeve, laughing."] = "wringt lachend einen Ärmelsaum aus.",
	["wrinkles their nose and holds an invisible shard at arm's length."] = "rümpft die Nase und hält einen unsichtbaren Splitter mit ausgestrecktem Arm von sich.",
	["wrinkles their nose and leans slowly away from their own armpit."] = "rümpft die Nase und lehnt sich langsam von der eigenen Achsel weg.",
	["writes a line of small, tidy letters in the ashes with a stick, and leaves the last word unfinished."] = "schreibt mit einem Stock eine Zeile kleiner, sauberer Buchstaben in die Asche und lässt das letzte Wort unvollendet.",
	["yanks an invisible strap twice, then lets it go with a sigh."] = "reißt zweimal an einem unsichtbaren Riemen und lässt ihn dann seufzend los.",
	["yanks one hand sharply backward, then stares at the empty space in front of them."] = "reißt eine Hand ruckartig zurück und starrt dann auf die leere Stelle davor.",
	["yet hold me and wait, and I'll bring you back home. What am I?"] = "doch haltet mich und wartet, dann bring ich euch heim an den Herd. Was bin ich?",
	["your bags"] = "eure Taschen",
	["{target}, I should warn you. People have been talking."] = "{target}, ich sollte dich warnen. Die Leute reden.",
	["{target}, an old friend and I have argued for years over whether soup is a food or a drink. We've ruined a lot of good soup over it."] = "{target}, eine alte Freundin und ich streiten seit Jahren darüber, ob Suppe ein Essen oder ein Getränk ist. Dabei ist schon viel gute Suppe kalt geworden.",
	["{target}, would you mind if I told you something about where you're sitting? It's nothing bad. Probably."] = "{target}, darf ich dir was über den Platz erzählen, auf dem du sitzt? Nichts Schlimmes. Wahrscheinlich.",
	["{target}, you seem sensible, so I'll tell you what I tell everyone who eats at my fire."] = "{target}, du wirkst vernünftig, also sag ich dir, was ich jedem sage, der an meinem Feuer isst.",
})
